const path = require("node:path");
const tsParser = require("@typescript-eslint/parser");
const { importBoundaryViolation } = require("./scripts/import_boundaries.cjs");

module.exports = [
  {
    files: ["src/**/*.ts"],
    ignores: ["dist/**"],
    languageOptions: {
      parser: tsParser,
      parserOptions: { ecmaVersion: 2022, sourceType: "module" },
    },
    plugins: {
      boundaries: {
        rules: {
          imports: {
            meta: { type: "problem", schema: [], messages: { forbidden: "{{violation}}" } },
            create(context) {
              function check(node, source) {
                const specifier =
                  source?.value ??
                  (source?.type === "TemplateLiteral" && source.expressions.length === 0
                    ? source.quasis[0].value.cooked
                    : null);
                if (typeof specifier !== "string") return;
                const violation = importBoundaryViolation(
                  path.join(__dirname, "src"),
                  context.filename,
                  specifier,
                );
                if (violation)
                  context.report({ node, messageId: "forbidden", data: { violation } });
              }
              return {
                ImportDeclaration: (node) => check(node, node.source),
                ExportNamedDeclaration: (node) => check(node, node.source),
                ExportAllDeclaration: (node) => check(node, node.source),
                ImportExpression: (node) => check(node, node.source),
                TSImportType: (node) => check(node, node.argument),
                TSExternalModuleReference: (node) => check(node, node.expression),
                CallExpression(node) {
                  if (node.callee.type === "Identifier" && node.callee.name === "require")
                    check(node, node.arguments[0]);
                },
              };
            },
          },
        },
      },
    },
    rules: { "boundaries/imports": "error" },
  },
];

/**
 * 负责应用与共享展示源码的 AST 中文字面扫描。输入为固定公开源码根及已审查的文件／文本／次数例外；
 * 输出为未获准中文字面和过期例外诊断，CLI 只报告失败，不改源码、词典或例外清单。
 * 仓库入口逐段拒绝符号链接根，遍历时跳过链接项；私有配置与认证不作为扫描输入。
 * 唯一翻译所有者清单只豁免其 exported const zhCN 对象的直接中文值，不豁免相邻代码或整个目录。
 */
import ts from "typescript";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { lstat, readFile, readdir } from "node:fs/promises";

export const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const han = /\p{Script=Han}/u;
const translationOwners = new Set([
  "packages/game-text/src/messages/common.ts",
  "packages/game-text/src/messages/runtime.ts",
  "packages/game-text/src/messages/agents.ts",
  "packages/game-text/src/messages/replay.ts",
  "packages/game-text/src/messages/audit.ts",
  "packages/game-text/src/messages/features/classic.ts",
  "packages/game-text/src/messages/features/identity.ts",
  "packages/game-text/src/messages/features/gifts-relations.ts",
  "packages/game-text/src/messages/features/night-modifiers.ts",
  "packages/game-text/src/messages/features/mist-radiant.ts",
  "packages/game-text/src/messages/features/noble-fragrant.ts",
  "packages/game-text/src/messages/features/animal-dream.ts",
]);
/** @typedef {{ file: string, text: string, line: number }} ChineseLiteral */
/** @typedef {{ file: string, text: string, count: number, reason: string }} LiteralException */
/** 检查所给源码的字符串、模板片段和 JSX；注释不作为字面，仓库入口不扫描测试／fixture。 */
/** @param {string} file @param {string} source */
export function collectChineseLiterals(file, source) {
  const parsed = ts.createSourceFile(
    file,
    source,
    ts.ScriptTarget.Latest,
    true,
    /\.[jt]sx$/.test(file) ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
  );
  /** @type {Set<import("typescript").ObjectLiteralExpression>} */
  const translationObjects = new Set();
  if (translationOwners.has(file)) {
    for (const statement of parsed.statements) {
      if (
        !ts.isVariableStatement(statement) ||
        !(statement.declarationList.flags & ts.NodeFlags.Const) ||
        !statement.modifiers?.some((modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword)
      )
        continue;
      for (const declaration of statement.declarationList.declarations) {
        if (!ts.isIdentifier(declaration.name) || declaration.name.text !== "zhCN") continue;
        let value = declaration.initializer;
        while (value && (ts.isAsExpression(value) || ts.isSatisfiesExpression(value)))
          value = value.expression;
        if (value && ts.isObjectLiteralExpression(value)) translationObjects.add(value);
      }
    }
  }
  /** @type {ChineseLiteral[]} */
  const found = [];
  /** @param {import("typescript").Node} node */
  const visit = (node) => {
    if (
      ts.isStringLiteral(node) ||
      ts.isNoSubstitutionTemplateLiteral(node) ||
      ts.isTemplateHead(node) ||
      ts.isTemplateMiddle(node) ||
      ts.isTemplateTail(node) ||
      ts.isJsxText(node)
    ) {
      const property = node.parent;
      // 只放行登记 owner 中 zhCN 对象的直接 property 值；键名和相邻表达式仍走普通扫描。
      const translationValue =
        (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) &&
        ts.isPropertyAssignment(property) &&
        property.initializer === node &&
        ts.isObjectLiteralExpression(property.parent) &&
        translationObjects.has(property.parent);
      if (han.test(node.text) && !translationValue)
        found.push({
          file,
          text: node.text,
          line: parsed.getLineAndCharacterOfPosition(node.getStart(parsed)).line + 1,
        });
    }
    ts.forEachChild(node, visit);
  };
  visit(parsed);
  return found;
}
/** @param {readonly ChineseLiteral[]} found @param {readonly LiteralException[]} exceptions */
export function verifyLiteralExceptions(found, exceptions) {
  /** @type {Map<string, LiteralException>} */
  const expected = new Map();
  for (const entry of exceptions) {
    if (!entry.reason || !Number.isSafeInteger(entry.count) || entry.count < 1)
      throw new Error("i18n_scan_exception_invalid");
    const key = JSON.stringify([entry.file, entry.text]);
    if (expected.has(key)) throw new Error("i18n_scan_exception_duplicate");
    expected.set(key, entry);
  }
  /** @type {Map<string, number>} */
  const actual = new Map();
  for (const entry of found) {
    const key = JSON.stringify([entry.file, entry.text]);
    actual.set(key, (actual.get(key) ?? 0) + 1);
  }
  const problems = [];
  for (const entry of found) {
    const key = JSON.stringify([entry.file, entry.text]);
    const exception = expected.get(key);
    if (!exception || (actual.get(key) ?? 0) > exception.count)
      problems.push(`${entry.file}:${entry.line}: unapproved Chinese literal`);
  }
  // 例外的实际出现数必须精确等于登记数；消失或少于原数同样过期，不能留下长期宽豁免。
  for (const [key, entry] of expected)
    if (actual.get(key) !== entry.count)
      problems.push(`${entry.file}: stale or changed i18n exception`);
  return problems;
}
/** 只读取配置在本入口的公开源码子目录。
 * @param {string} publicRoot 仓库根或测试自有根路径。
 */
export async function scanRepository(publicRoot = repositoryRoot) {
  /** @type {ChineseLiteral[]} */
  const found = [];
  const absoluteRoot = path.resolve(publicRoot);
  /** @param {string} directory @param {boolean} [optionalRoot] @returns {Promise<boolean>} */
  const sourceRootIsPresent = async (directory, optionalRoot = false) => {
    // 在读取前逐段核父路径，避免公开子目录或其祖先被链接替换后逃离原输入边界。
    const absolute = path.join(absoluteRoot, directory),
      filesystemRoot = path.parse(absolute).root;
    let current = filesystemRoot;
    for (const segment of absolute.slice(filesystemRoot.length).split(path.sep)) {
      current = path.join(current, segment);
      let stats;
      try {
        stats = await lstat(current);
      } catch (error) {
        if (
          optionalRoot &&
          typeof error === "object" &&
          error !== null &&
          "code" in error &&
          error.code === "ENOENT"
        )
          return false;
        throw error;
      }
      const relative = path.relative(absoluteRoot, current) || ".";
      if (stats.isSymbolicLink()) throw new Error(`i18n_scan_source_symlink: ${relative}`);
      if (!stats.isDirectory())
        throw Object.assign(new Error(`i18n_scan_source_directory_invalid: ${relative}`), {
          code: "ENOTDIR",
        });
    }
    return true;
  };
  /** @param {string} directory @returns {Promise<void>} */
  const walk = async (directory) => {
    const entries = await readdir(path.join(absoluteRoot, directory), { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isSymbolicLink()) continue;
      const file = `${directory}/${entry.name}`;
      if (entry.isDirectory()) await walk(file);
      else if (entry.isFile() && /\.(?:[jt]sx?|[cm]js)$/.test(entry.name))
        found.push(
          ...collectChineseLiterals(file, await readFile(path.join(absoluteRoot, file), "utf8")),
        );
    }
  };
  for (const directory of ["backend/src", "frontend/src", "frontend/scripts"]) {
    await sourceRootIsPresent(directory);
    await walk(directory);
  }
  for (const directory of ["packages/game-text/src", "packages/game-presentation/src"])
    if (await sourceRootIsPresent(directory, true)) await walk(directory);
  return found;
}
if (import.meta.main) {
  const found = await scanRepository();
  const exceptions = JSON.parse(
    await readFile(path.join(repositoryRoot, "docs/expansion/i18n-source-exceptions.json"), "utf8"),
  );
  const problems = verifyLiteralExceptions(found, exceptions);
  if (problems.length) {
    for (const problem of problems) console.error(problem);
    process.exitCode = 1;
  } else
    console.log(
      `i18n source scan passed (${found.length} documented compatibility/native-language literals)`,
    );
}

#!/usr/bin/env node
/**
 * 负责旧层级导入规则的命令行扫描。输入为工作目录相对源码根，默认 src；输出为字面路径违规列表或成功，失败退出 1。
 * 按文件系统目录项递归读取 .ts，AST 识别导入、导出、require、动态 import、import type 和 import equals 的字面模块名。
 * 扫描只调用本地路径判定器，不执行被扫模块或写源码；非字面拼接路径不在检查范围，角色／共享包约束另由架构门禁负责。
 */
import fs from "node:fs";
import path from "node:path";
import ts from "typescript";
import { importBoundaryViolation } from "./import_boundaries.cjs";

// 维持原 cwd／argv 默认值；这里不对输入根额外 realpath，也不扩大 .ts 以外的发现范围。
const rootDir = path.resolve(process.cwd(), process.argv[2] ?? "src");
/** @type {string[]} */
const errors = [];

/** @param {string} dir */
function walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const abs = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(abs);
    else if (entry.isFile() && abs.endsWith(".ts")) checkFile(abs);
  }
}

/** @param {string} filePath */
function checkFile(filePath) {
  const source = ts.createSourceFile(
    filePath,
    fs.readFileSync(filePath, "utf8"),
    ts.ScriptTarget.Latest,
    true,
  );
  /** @param {import("typescript").Node} node */
  function visit(node) {
    // 只读取原字面模块名；覆盖重导、运行调用和类型位置，不执行表达式来猜测动态路径。
    let specifier;
    if (ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) {
      specifier = node.moduleSpecifier;
    } else if (
      ts.isCallExpression(node) &&
      (node.expression.kind === ts.SyntaxKind.ImportKeyword ||
        (ts.isIdentifier(node.expression) && node.expression.text === "require"))
    ) {
      specifier = node.arguments[0];
    } else if (ts.isExternalModuleReference(node)) {
      specifier = node.expression;
    } else if (ts.isImportTypeNode(node) && ts.isLiteralTypeNode(node.argument)) {
      specifier = node.argument.literal;
    }
    if (
      specifier &&
      (ts.isStringLiteral(specifier) || ts.isNoSubstitutionTemplateLiteral(specifier))
    ) {
      const violation = importBoundaryViolation(rootDir, filePath, specifier.text);
      if (violation) errors.push(`${path.relative(process.cwd(), filePath)}: ${violation}`);
    }
    ts.forEachChild(node, visit);
  }
  visit(source);
}

walk(rootDir);

if (errors.length > 0) {
  console.error("[import-boundary] dependency violations:");
  for (const item of errors) console.error(`- ${item}`);
  process.exit(1);
}

console.log("[import-boundary] ok");

import { mkdtemp, mkdir, readdir, writeFile, symlink, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const root = await mkdtemp(path.join(tmpdir(), "awa-seer-baseline-"));
const baseline = "eb4f026a38205d420cc2172b32fe23a29cb00da0";
try {
  const archive = spawnSync("git", ["archive", baseline, "backend/src", "packages"], {
    cwd: repo,
    maxBuffer: 64 * 1024 * 1024,
  });
  if (archive.status !== 0) throw new Error(archive.stderr.toString());
  const extracted = spawnSync("tar", ["-x", "-C", root], { input: archive.stdout });
  if (extracted.status !== 0) throw new Error(extracted.stderr.toString());
  const deps = path.join(root, "backend/node_modules");
  await mkdir(deps);
  for (const name of await readdir(path.join(repo, "backend/node_modules"))) {
    if (name === "@ai-werewolf-arena") {
      await mkdir(path.join(deps, name));
      for (const pkg of await readdir(path.join(repo, "backend/node_modules", name)))
        await symlink(path.join(root, "packages", pkg), path.join(deps, name, pkg));
    } else await symlink(path.join(repo, "backend/node_modules", name), path.join(deps, name));
  }
  for (const name of ["game-text", "replay-contract"])
    await symlink(deps, path.join(root, "packages", name, "node_modules"));
  await writeFile(
    path.join(root, "probe.ts"),
    `
import { bootstrapGame } from './backend/src/app/bootstrap';
import { sixPlayerMvpConfig } from './backend/src/runtime/scenarios/six_player_mvp';
import { Role } from './backend/src/core';
const game = bootstrapGame(sixPlayerMvpConfig, { fixedRoles: [Role.Guard, Role.Wolf, Role.Wolf, Role.Villager, Role.Villager, Role.Seer] });
let actual;
await game.phaseManager.runSingleCycle({ async getAction(request) {
  if (request.context.stage === 'seer') actual = { actorId: request.actorId, day: request.context.day, stage: request.context.stage, allowedTools: request.allowedTools, turn_constraints: request.context.turn_constraints };
  return null;
}}, 1);
if (!actual || actual.turn_constraints.min_valid_actions !== 1) throw new Error('baseline_seer_not_required');
console.log(JSON.stringify({baseline: '${baseline}', request: actual}, null, 2));
`,
  );
  const probe = spawnSync("bun", [path.join(root, "probe.ts")], { cwd: root });
  if (probe.status !== 0) throw new Error(probe.stderr.toString());
  const actual = JSON.parse(probe.stdout.toString());
  const { readFile } = await import("node:fs/promises");
  const fixture = JSON.parse(
    await readFile(path.join(repo, "backend/tests/support/seer_baseline_request.json"), "utf8"),
  );
  if (JSON.stringify(actual) !== JSON.stringify(fixture))
    throw new Error("baseline_fixture_mismatch");
  console.log(JSON.stringify(actual, null, 2));
} finally {
  await rm(root, { recursive: true, force: true });
}

/**
 * 负责旧应用层级的纯路径判定。输入为源码根、导入方路径与字面模块名；输出为首个禁止层级说明或 null。
 * 此处唯一声明旧层级表，按原 find 次序匹配同层／子目录；判断不读取文件、解析包出口或授予运行权限。
 * 相对与绝对路径按原规则规范化，包名保持不匹配；新角色／包边界仍由独立架构门禁核对，不能借 null 宣称全部结构合法。
 */
const path = require("node:path");

// 每项属于旧层级的禁止依赖集合；find 的先匹配顺序与原错误说明共同构成此工具的契约。
const boundaries = [
  {
    layer: "core",
    forbidden: ["app", "game", "ai", "runtime", "server", "infra", "recording", "audit", "replay"],
  },
  {
    layer: "game/engine",
    forbidden: ["app", "ai", "runtime", "server", "infra", "audit", "replay"],
  },
  {
    layer: "game/gateway",
    forbidden: ["app", "ai", "runtime", "server", "infra", "audit", "replay"],
  },
  {
    layer: "runtime/scenarios",
    forbidden: [
      "app",
      "ai",
      "game/engine",
      "game/gateway",
      "runtime",
      "server",
      "infra",
      "recording",
      "audit",
      "replay",
    ],
  },
  { layer: "recording", forbidden: ["app", "ai", "runtime", "game", "audit", "replay"] },
];

/** @param {string} file @param {string} directory */
function within(file, directory) {
  return file === directory || file.startsWith(`${directory}/`);
}

/** @param {string} rootDir @param {string} filePath @param {string} specifier */
function importBoundaryViolation(rootDir, filePath, specifier) {
  if (!specifier.startsWith(".") && !path.isAbsolute(specifier)) return null;
  const source = path.relative(rootDir, filePath).replace(/\\/g, "/");
  const boundary = boundaries.find(({ layer }) => within(source, layer));
  if (!boundary) return null;
  // 仅按导入方位置规范化路径并去除原后缀，不访问目标文件或推导实际 package 声明。
  const target = path
    .relative(rootDir, path.resolve(path.dirname(filePath), specifier))
    .replace(/\\/g, "/")
    .replace(/\.(?:[cm]?ts|[cm]?js)$/, "");
  if (within(target, boundary.layer)) return null;
  const forbidden = boundary.forbidden.find((layer) => within(target, layer));
  return forbidden
    ? `${boundary.layer} imports forbidden layer "${forbidden}" via "${specifier}"`
    : null;
}

module.exports = { importBoundaryViolation };

/**
 * 负责在声明的决策与来源冻结边界执行显式夜间故障计划。输入为计划描述与当前 World 引用；
 * 输出保留实际故障及计划消费检查。这个受控故障驱动不创造正常角色动作，也不改变 RNG 抽取顺序。
 */
import { createAliveComponent } from "../observation/component-presentation";
import { types } from "node:util";
import { z } from "zod";
import { readFaultPlan, type FaultPlan, type FaultStep } from "../../core/domain/fault_plan";
export { readFaultPlan, type FaultPlan, type FaultStep } from "../../core/domain/fault_plan";
const positive = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
function inputData(value: unknown): unknown {
  // Decision boundary is equally finite plain data; use the core snapshot helper.
  return readFaultPlanData(value);
}
import { readFaultPlanData } from "../../core/domain/fault_plan";
import { COMPONENT, aliveLifeVersion, aliveLifeDescriptor, type AliveComponent, type World } from "../../core";

const nativePromiseThen = Promise.prototype.then;
const nativePromiseSpecies = Object.getOwnPropertyDescriptor(Promise, Symbol.species)?.get;
export interface FaultDecisionBoundary {
  readonly actorId: number;
  readonly day: number;
  readonly stage: "demon_hunter";
  readonly turn: 1;
  readonly targetId: number;
}
export interface AppliedFault {
  readonly step: FaultStep;
  readonly originalVersion: number;
  readonly replacementVersion: number;
}

/** Explicit offline input; cancellation facts are never consulted to execute a fault. */
export class NightFaultPlan {
  readonly plan: FaultPlan;
  private readonly consumed = new Set<string>();
  private lastDay = 0;
  private failed = false;
  constructor(
    private readonly world: World,
    input: unknown,
  ) {
    this.plan = readFaultPlan(input);
    for (const step of this.plan.steps)
      if (
        !world.hasEntity(step.at.afterDecision.actorId) ||
        !world.hasEntity(step.mutation.playerId)
      )
        throw new Error("fault_plan_player_unknown");
  }

  /** Caller supplies an actual committed choice, before any source in this wave writes Alive. */
  applyBeforeNightSourceFreeze(
    day: number,
    decision: FaultDecisionBoundary | null,
    recordApplied: (fault: AppliedFault) => void,
  ): readonly string[] {
    if (this.failed) throw new Error("fault_plan_failed");
    try {
      return this.apply(day, decision, recordApplied);
    } catch (error) {
      this.failed = true;
      throw error;
    }
  }

  private apply(
    day: number,
    decision: FaultDecisionBoundary | null,
    recordApplied: (fault: AppliedFault) => void,
  ): readonly string[] {
    if (
      typeof recordApplied !== "function" ||
      types.isProxy(recordApplied) ||
      types.isAsyncFunction(recordApplied) ||
      types.isGeneratorFunction(recordApplied)
    )
      throw new Error("fault_plan_recorder_invalid");
    if (!Number.isSafeInteger(day) || day < 1 || day <= this.lastDay)
      throw new Error("fault_plan_boundary_repeated");
    if (this.plan.steps.some((step) => step.at.day < day && !this.consumed.has(step.id)))
      throw new Error("fault_plan_boundary_missed");
    const step = this.plan.steps.find((item) => item.at.day === day);
    if (!step) {
      this.lastDay = day;
      return [];
    }
    if (decision !== null)
      decision = z
        .strictObject({
          actorId: positive,
          day: positive.min(2),
          stage: z.literal("demon_hunter"),
          turn: z.literal(1),
          targetId: positive,
        })
        .parse(inputData(decision));
    if (
      !decision ||
      decision.targetId === decision.actorId ||
      !this.world.hasEntity(decision.targetId) ||
      decision.day !== day ||
      decision.actorId !== step.at.afterDecision.actorId ||
      decision.stage !== step.at.afterDecision.stage ||
      decision.turn !== step.at.afterDecision.turn ||
      ![decision.actorId, decision.targetId].includes(step.mutation.playerId)
    )
      throw new Error("fault_plan_decision_boundary_invalid");
    const original = this.world.getComponent(step.mutation.playerId, COMPONENT.Alive),
      originalVersion = original && aliveLifeVersion(original);
    if (!original || types.isProxy(original) || originalVersion === undefined)
      throw new Error("fault_plan_original_life_invalid");
    const originalDescriptor = aliveLifeDescriptor(original),
      currentDescriptor = Object.getOwnPropertyDescriptor(original, "alive");
    if (
      !originalDescriptor ||
      !currentDescriptor ||
      currentDescriptor.get !== originalDescriptor.get ||
      currentDescriptor.set !== originalDescriptor.set ||
      currentDescriptor.enumerable !== originalDescriptor.enumerable ||
      currentDescriptor.configurable !== originalDescriptor.configurable
    )
      throw new Error("fault_plan_original_life_invalid");
    if (original.alive !== true) throw new Error("fault_plan_original_life_invalid");
    const replacement = createAliveComponent(true, this.world.locale);
    this.world.addComponent(step.mutation.playerId, COMPONENT.Alive, replacement);
    this.consumed.add(step.id);
    this.lastDay = day;
    const result: unknown = recordApplied({
      step,
      originalVersion,
      replacementVersion: aliveLifeVersion(replacement)!,
    });
    if (result !== undefined) {
      if (
        types.isPromise(result) &&
        !types.isProxy(result) &&
        Object.getPrototypeOf(result) === Promise.prototype &&
        !Object.hasOwn(result, "constructor") &&
        Object.getOwnPropertyDescriptor(Promise.prototype, "constructor")?.value === Promise &&
        Object.getOwnPropertyDescriptor(Promise, Symbol.species)?.get === nativePromiseSpecies
      )
        nativePromiseThen.call(result, undefined, () => undefined);
      throw new Error("fault_plan_recorder_not_sync");
    }
    return Object.freeze([step.id]);
  }

  assertConsumed(): void {
    if (this.failed) throw new Error("fault_plan_failed");
    if (this.consumed.size !== this.plan.steps.length) throw new Error("fault_plan_unconsumed");
  }
}

