/**
 * Freeze public production inputs for the two-build refactor comparison.
 * Input: an explicit Git revision or current source tree; output: immutable-by-
 * verification source/lock manifest and an isolated dependency resolution tree.
 * Workspace packages resolve inside each snapshot. Installed external libraries
 * are copied only when their resolved lock entries match the requested build.
 * Dependency bytes are verified before/after execution; this detects edits and is not
 * filesystem write protection. Local auth/config/records/Git are never copied.
 */
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import {
  cp,
  lstat,
  mkdir,
  readFile,
  readdir,
  realpath,
  readlink,
  symlink,
  writeFile,
} from "node:fs/promises";
import path from "node:path";
import { isPublicInventoryPath } from "./inventory";

export interface BuildSnapshot {
  root: string;
  revision: string | null;
  files: Array<{ path: string; sha256: string }>;
  digest: string;
  dependencies: { root: string; digest: string };
}
const hash = (data: string | Uint8Array) => createHash("sha256").update(data).digest("hex");
const buildMetadata = [
  "package.json",
  "bun.lock",
  "bunfig.toml",
  "tsconfig.json",
  "backend/package.json",
  "frontend/package.json",
  "backend/tsconfig.json",
  "frontend/tsconfig.json",
];

async function rejectSourceSymlinkAncestors(root: string, relative: string): Promise<void> {
  let current = root;
  for (const segment of relative.split("/")) {
    current = path.join(current, segment);
    if ((await lstat(current)).isSymbolicLink()) throw Error("snapshot_source_ancestor_symlink");
  }
}

async function existingBuildMetadata(root: string): Promise<string[]> {
  const result: string[] = [];
  for (const name of buildMetadata) {
    try {
      await rejectSourceSymlinkAncestors(root, name);
      if (!(await lstat(path.join(root, name))).isFile())
        throw Error(`snapshot_source_not_file: ${name}`);
      result.push(name);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    }
  }
  for (const owner of ["", "backend", "frontend"]) {
    let entries: import("node:fs").Dirent[];
    try {
      if (owner) await rejectSourceSymlinkAncestors(root, owner);
      entries = await readdir(path.join(root, owner), { withFileTypes: true });
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") continue;
      throw error;
    }
    for (const entry of entries) {
      if (!/^tsconfig(?:\.[^.]+)*\.json$/.test(entry.name)) continue;
      if (!entry.isFile()) throw Error("snapshot_compiler_metadata_not_file");
      result.push(path.posix.join(owner, entry.name));
    }
  }
  return [...new Set(result)];
}

const sourcePath = (name: string) =>
  isPublicInventoryPath(name) &&
  (/^(backend\/src\/|packages\/[^/]+\/(?:src\/|package\.json$|tsconfig(?:\.[^.]+)*\.json$))/.test(
    name,
  ) ||
    buildMetadata.includes(name) ||
    /^(?:backend\/|frontend\/)?tsconfig(?:\.[^.]+)*\.json$/.test(name));

async function listFiles(root: string, directory: string): Promise<string[]> {
  await rejectSourceSymlinkAncestors(root, directory);
  const result: string[] = [];
  for (const entry of (await readdir(path.join(root, directory), { withFileTypes: true })).sort(
    (a, b) => a.name.localeCompare(b.name),
  )) {
    if (entry.name === "node_modules") continue;
    const name = path.posix.join(directory, entry.name);
    if (entry.isSymbolicLink()) throw Error(`snapshot_source_symlink: ${name}`);
    if (entry.isDirectory()) result.push(...(await listFiles(root, name)));
    else if (entry.isFile() && sourcePath(name)) result.push(name);
  }
  return result;
}

/** Hash physical dependency bytes and symlink destinations without following cycles. */
export async function dependencyDigest(root: string): Promise<string> {
  const digest = createHash("sha256");
  const walk = async (directory: string) => {
    for (const entry of (await readdir(path.join(root, directory), { withFileTypes: true })).sort(
      (a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0),
    )) {
      const name = path.posix.join(directory, entry.name);
      if (entry.isDirectory()) await walk(name);
      else {
        digest.update(name).update("\0");
        if (entry.isSymbolicLink()) digest.update(await readlink(path.join(root, name)));
        else if (entry.isFile()) digest.update(await readFile(path.join(root, name)));
        else throw Error(`snapshot_dependency_not_file: ${name}`);
        digest.update("\0");
      }
    }
  };
  await walk("");
  return digest.digest("hex");
}

async function installedDependencyDigest(root: string): Promise<string> {
  const digest = createHash("sha256");
  const owners = [
    "",
    "backend",
    "frontend",
    ...(await readdir(path.join(root, "packages")).then((names) =>
      names.map((name) => `packages/${name}`),
    )),
  ];
  for (const owner of owners)
    digest
      .update(owner)
      .update("\0")
      .update(await dependencyDigest(path.join(root, owner, "node_modules")))
      .update("\0");
  return digest.digest("hex");
}

async function installDependencies(repository: string, root: string): Promise<void> {
  const locked = Bun.JSONC.parse(await readFile(path.join(root, "bun.lock"), "utf8")) as {
    packages: Record<string, unknown[]>;
  };
  const externalLock = async (directory: string) => {
    const parsed = Bun.JSONC.parse(await readFile(path.join(directory, "bun.lock"), "utf8")) as {
      packages: Record<string, unknown[]>;
    };
    return JSON.stringify(
      Object.entries(parsed.packages)
        .filter(
          ([, value]) =>
            typeof value[0] === "string" &&
            !value[0].startsWith("workspace:") &&
            !value[0].includes("@workspace:"),
        )
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
    );
  };
  if ((await externalLock(repository)) !== (await externalLock(root)))
    throw Error("snapshot_installed_resolved_lock_mismatch");
  const dependencyRoot = path.join(root, "node_modules/.bun");
  await mkdir(path.dirname(dependencyRoot), { recursive: true });
  await cp(path.join(repository, "node_modules/.bun"), dependencyRoot, {
    recursive: true,
    dereference: false,
    verbatimSymlinks: true,
  });
  const owners = [
    "",
    "backend",
    "frontend",
    ...(await readdir(path.join(root, "packages")).then((names) =>
      names.map((name) => `packages/${name}`),
    )),
  ];
  const workspaces = new Map<string, string>();
  for (const owner of owners.filter(Boolean)) {
    const manifest = JSON.parse(await readFile(path.join(root, owner, "package.json"), "utf8"));
    workspaces.set(manifest.name, path.join(root, owner));
  }
  for (const owner of owners) {
    const destination = path.join(root, owner, "node_modules");
    await mkdir(destination, { recursive: true });
    const manifest = JSON.parse(await readFile(path.join(root, owner, "package.json"), "utf8"));
    const names = new Set<string>([
      ...Object.keys(manifest.dependencies ?? {}),
      ...Object.keys(manifest.devDependencies ?? {}),
    ]);
    for (const name of names) {
      let target = workspaces.get(name);
      if (!target) {
        let original: string | undefined;
        for (const fallback of [owner, "backend", "frontend", ""]) {
          try {
            original = await realpath(path.join(repository, fallback, "node_modules", name));
            break;
          } catch {
            /* Try declared installed owner. */
          }
        }
        if (!original) throw Error(`snapshot_dependency_not_installed: ${name}`);
        const relative = path.relative(path.join(repository, "node_modules/.bun"), original);
        if (relative.startsWith("..") || path.isAbsolute(relative))
          throw Error(`snapshot_dependency_outside_store: ${name}`);
        target = path.join(dependencyRoot, relative);
        const installed = JSON.parse(await readFile(path.join(target, "package.json"), "utf8"));
        if (installed.name !== name) throw Error(`snapshot_dependency_name_mismatch: ${name}`);
        const resolution = locked.packages[name]?.[0];
        if (
          typeof resolution !== "string" ||
          resolution !== `${installed.name}@${installed.version}`
        )
          throw Error(`snapshot_dependency_version_mismatch: ${name}`);
      }
      await mkdir(path.dirname(path.join(destination, name)), { recursive: true });
      await symlink(target, path.join(destination, name));
    }
  }
  // The physical store must not contain links that escape into the current checkout.
  const check = async (directory: string) => {
    for (const entry of await readdir(directory, { withFileTypes: true })) {
      const file = path.join(directory, entry.name);
      if (entry.isDirectory()) await check(file);
      else if (entry.isSymbolicLink()) {
        const target = await realpath(file);
        if (!target.startsWith(`${root}${path.sep}`))
          throw Error(`snapshot_dependency_escaped: ${path.relative(root, file)}`);
      }
    }
  };
  for (const owner of owners) await check(path.join(root, owner, "node_modules"));
}

export async function freezeBuild(
  repository: string,
  root: string,
  revision: string | null,
): Promise<BuildSnapshot> {
  repository = await realpath(repository);
  root = path.resolve(root);
  if (root === repository || root.startsWith(`${repository}${path.sep}`))
    throw Error("snapshot_requires_external_directory");
  await mkdir(root, { recursive: true });
  if ((await lstat(root)).isSymbolicLink()) throw Error("snapshot_destination_symlink");
  root = await realpath(root);
  if (root === repository || root.startsWith(`${repository}${path.sep}`))
    throw Error("snapshot_requires_external_directory");
  if ((await readdir(root)).length) throw Error("snapshot_destination_not_empty");
  let files: string[];
  let commit: string | null = null;
  if (revision) {
    commit = execFileSync("git", ["rev-parse", `${revision}^{commit}`], {
      cwd: repository,
      encoding: "utf8",
    }).trim();
    files = execFileSync("git", ["ls-tree", "-r", "--name-only", commit], {
      cwd: repository,
      encoding: "utf8",
    })
      .trim()
      .split("\n")
      .filter(sourcePath)
      .sort();
    const archive = execFileSync("git", ["archive", commit, "--", ...files], {
      cwd: repository,
      maxBuffer: 64 * 1024 * 1024,
    });
    execFileSync("tar", ["-xf", "-", "-C", root], { input: archive });
  } else {
    files = [
      ...(await existingBuildMetadata(repository)),
      ...(await listFiles(repository, "backend/src")),
      ...(await listFiles(repository, "packages")),
    ].sort();
    for (const name of files) {
      if (!(await lstat(path.join(repository, name))).isFile())
        throw Error(`snapshot_source_not_file: ${name}`);
      await mkdir(path.dirname(path.join(root, name)), { recursive: true });
      await cp(path.join(repository, name), path.join(root, name));
    }
  }
  const rows = await Promise.all(
    files.map(async (name) => {
      if (!(await lstat(path.join(root, name))).isFile())
        throw Error(`snapshot_source_not_file: ${name}`);
      return { path: name, sha256: hash(await readFile(path.join(root, name))) };
    }),
  );
  await installDependencies(repository, root);
  const dependencyRoot = root;
  const snapshot = {
    root,
    revision: commit,
    files: rows,
    digest: hash(JSON.stringify(rows)),
    dependencies: { root: dependencyRoot, digest: await installedDependencyDigest(dependencyRoot) },
  };
  await writeFile(path.join(root, "build-snapshot.json"), JSON.stringify(snapshot, null, 2) + "\n");
  return snapshot;
}

export async function assertSnapshotUnchanged(
  snapshot: BuildSnapshot,
  options: { dependencies?: boolean } = {},
): Promise<void> {
  const currentFiles = [
    ...(await existingBuildMetadata(snapshot.root)),
    ...(await listFiles(snapshot.root, "backend/src")),
    ...(await listFiles(snapshot.root, "packages")),
  ].sort();
  if (
    JSON.stringify(currentFiles) !== JSON.stringify(snapshot.files.map((file) => file.path).sort())
  )
    throw Error("snapshot_source_membership_changed");
  for (const file of snapshot.files) {
    const name = path.join(snapshot.root, file.path);
    if (!(await lstat(name)).isFile() || hash(await readFile(name)) !== file.sha256)
      throw Error(`snapshot_input_changed: ${file.path}`);
  }
  if (
    options.dependencies !== false &&
    (await installedDependencyDigest(snapshot.dependencies.root)) !== snapshot.dependencies.digest
  )
    throw Error("snapshot_dependencies_changed");
}

/**
 * Comparator trust tests: literal traces must expose changed stock, knowledge,
 * causal boundaries, operations, unknown diagnostics and strict replay failures.
 * Only build identity and scratch artifact addresses are intentionally distinct.
 * This is tooling verification and does not claim gameplay rule acceptance.
 */
import { expect, test } from "bun:test";
import { comparableTrace, firstDifference } from "./differential";

function trace() {
  return {
    record: {
      metadata: { engine: { sourceHash: "old", lockHash: "lock", commit: "old" }, seed: "fixed" },
      decisions: [
        {
          openedAfterSettlement: 0,
          openedAtEventCount: 2,
          settleOrder: 1,
          request: { context: { known: false } },
        },
      ],
      checkpoints: [{ operationCount: 1, stock: 2 }],
      events: [{ timestamp: 1_700_000_000_000, payload: { target: 3 }, audience: [2] }],
      operations: [{ op: "pay", status: "committed", event_count: 2 }],
    },
    strictReplay: { recordDir: "/tmp/old", decisionCount: 1, eventCount: 1 },
  };
}
test("build fingerprints and scratch paths do not replace gameplay equality", () => {
  const a = trace(),
    b = trace();
  b.record.metadata.engine.sourceHash = "new";
  b.record.metadata.engine.commit = "new";
  b.strictReplay.recordDir = "/tmp/new";
  expect(firstDifference(comparableTrace(a), comparableTrace(b))).toBeNull();
  expect(a.record.metadata.engine.sourceHash).toBe("old");
});
for (const change of [
  "stock",
  "known",
  "opening",
  "settlement",
  "operation",
  "audience",
  "unknown",
  "replay",
  "timestamp",
  "engine-id",
  "engine-unknown",
])
  test(`does not hide changed ${change}`, () => {
    const a = trace(),
      b = trace();
    if (change === "stock") b.record.checkpoints[0]!.stock--;
    if (change === "known") b.record.decisions[0]!.request.context.known = true;
    if (change === "opening") b.record.decisions[0]!.openedAtEventCount++;
    if (change === "settlement") b.record.decisions[0]!.settleOrder++;
    if (change === "operation") b.record.operations[0]!.status = "failed";
    if (change === "audience") b.record.events[0]!.audience = [3];
    if (change === "replay") b.strictReplay.decisionCount++;
    if (change === "timestamp") b.record.events[0]!.timestamp++;
    if (change === "unknown") Object.assign(b.record, { unexpectedDiagnostic: 1 });
    if (change === "engine-id") Object.assign(b.record.metadata.engine, { id: "other-engine" });
    if (change === "engine-unknown") Object.assign(b.record.metadata.engine, { newProtocol: true });
    expect(firstDifference(comparableTrace(a), comparableTrace(b))).not.toBeNull();
  });
test("missing native replay is rejected rather than skipped", () => {
  expect(() => comparableTrace({ record: { metadata: {} } })).toThrow("differential_trace_invalid");
});

/**
 * Compare two independently generated strict traces from fixed engine snapshots.
 * Input fingerprints may differ only as explicitly identified build metadata;
 * every request/event/operation/stock/knowledge/result/causal field is compared.
 * No unknown field is suppressed. Each child must replay under its own engine.
 * This verifies mechanical equivalence, not rule correctness or F01/F02 changes.
 */
import { createHash } from "node:crypto";
import { readFile, mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { assertSnapshotUnchanged, freezeBuild, type BuildSnapshot } from "./build-snapshot";

export function comparableTrace(trace: unknown): unknown {
  if (!trace || typeof trace !== "object") throw Error("differential_trace_invalid");
  const copy = structuredClone(trace) as {
    record?: { metadata?: Record<string, unknown> };
    strictReplay?: Record<string, unknown>;
  };
  if (!copy.record?.metadata || !copy.strictReplay) throw Error("differential_trace_invalid");
  // Only these version fields differ. Engine ID and unknown fields still compare.
  const engine = copy.record.metadata.engine;
  if (!engine || typeof engine !== "object") throw Error("differential_engine_missing");
  for (const name of ["sourceHash", "lockHash", "commit"])
    delete (engine as Record<string, unknown>)[name];
  // Output location is an artifact address, not a field in the recorded protocol.
  delete copy.strictReplay.recordDir;
  return copy;
}

export function firstDifference(a: unknown, b: unknown, prefix = "$ "): string | null {
  if (Object.is(a, b)) return null;
  if (!a || !b || typeof a !== "object" || typeof b !== "object") return prefix.trim();
  if (Array.isArray(a) !== Array.isArray(b)) return prefix.trim();
  const ak = Object.keys(a).sort(),
    bk = Object.keys(b).sort();
  if (JSON.stringify(ak) !== JSON.stringify(bk)) return `${prefix.trim()}:keys`;
  for (const key of ak) {
    const different = firstDifference(
      (a as Record<string, unknown>)[key],
      (b as Record<string, unknown>)[key],
      `${prefix.trim()}.${key}`,
    );
    if (different) return different;
  }
  return null;
}

async function trace(build: BuildSnapshot, scenario: string, scratch: string, layout?: string) {
  await assertSnapshotUnchanged(build, { dependencies: false });
  const args = [
    process.execPath,
    "--no-env-file",
    path.join(import.meta.dir, "trace-game.ts"),
    build.root,
    scenario,
    scratch,
    ...(layout ? [layout] : []),
  ];
  const child = Bun.spawn(args, {
    cwd: build.root,
    stdout: "pipe",
    stderr: "pipe",
    env: { PATH: process.env.PATH ?? "", TMPDIR: "/tmp" },
  });
  const [code, stdout, stderr] = await Promise.all([
    child.exited,
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
  ]);
  await assertSnapshotUnchanged(build, { dependencies: false });
  if (code !== 0) throw Error(`differential_child_failed: ${code}\n${stdout}\n${stderr}`);
  return JSON.parse(await readFile(path.join(scratch, "trace.json"), "utf8"));
}

export async function compareBuilds(options: {
  repository: string;
  scratch: string;
  baselineRevision: string;
  scenarios: string[];
  candidateLayout?: string;
  fixedBuilds?: { baseline: BuildSnapshot; candidate: BuildSnapshot };
}): Promise<void> {
  const scratch = path.resolve(options.scratch);
  await mkdir(scratch, { recursive: true });
  const baseline =
    options.fixedBuilds?.baseline ??
    (await freezeBuild(
      options.repository,
      path.join(scratch, "baseline"),
      options.baselineRevision,
    ));
  const candidate =
    options.fixedBuilds?.candidate ??
    (await freezeBuild(options.repository, path.join(scratch, "candidate"), null));
  if (baseline.revision !== options.baselineRevision && options.fixedBuilds)
    throw Error("differential_fixed_baseline_revision_mismatch");
  await assertSnapshotUnchanged(baseline);
  await assertSnapshotUnchanged(candidate);
  const driverFiles = [
    "trace-game.ts",
    "transcripts.ts",
    "differential.ts",
    "build-snapshot.ts",
    "inventory.ts",
  ];
  const driverDigest = async () => {
    const digest = createHash("sha256");
    for (const name of driverFiles)
      digest
        .update(name)
        .update("\0")
        .update(await readFile(path.join(import.meta.dir, name)))
        .update("\0");
    if (options.candidateLayout)
      digest.update("candidate-layout").update(await readFile(options.candidateLayout));
    return digest.digest("hex");
  };
  const driverHash = await driverDigest();
  const report = [];
  let failure: unknown;
  try {
    for (const [index, scenario] of options.scenarios.entries()) {
      const input = path.resolve(scenario),
        bytes = await readFile(input);
      const previous = await trace(baseline, input, path.join(scratch, `case-${index}/baseline`));
      if ((await driverDigest()) !== driverHash) throw Error("differential_driver_changed");
      const current = await trace(
        candidate,
        input,
        path.join(scratch, `case-${index}/candidate`),
        options.candidateLayout,
      );
      if (!bytes.equals(await readFile(input))) throw Error("differential_scenario_changed");
      if ((await driverDigest()) !== driverHash) throw Error("differential_driver_changed");
      const difference = firstDifference(comparableTrace(previous), comparableTrace(current));
      report.push({
        scenario: path.basename(input),
        inputHash: createHash("sha256").update(bytes).digest("hex"),
        difference,
      });
      await writeFile(
        path.join(scratch, "report.json"),
        JSON.stringify(
          { baseline: baseline.digest, candidate: candidate.digest, driverHash, cases: report },
          null,
          2,
        ) + "\n",
      );
      if (difference) throw Error(`differential_mismatch: ${scenario} at ${difference}`);
    }
  } catch (error) {
    failure = error;
  }
  // Verify large dependency inventories around the complete batch. Per-child
  // source/metadata byte and membership verification remains immediate.
  const verified = await Promise.allSettled([
    assertSnapshotUnchanged(baseline),
    assertSnapshotUnchanged(candidate),
  ]);
  const errors = [
    ...(failure ? [failure] : []),
    ...verified.flatMap((result) => (result.status === "rejected" ? [result.reason] : [])),
  ];
  if (errors.length === 1) throw errors[0];
  if (errors.length) throw new AggregateError(errors, "differential_batch_failed");
}

if (import.meta.main) {
  const [repository, scratch, baselineRevision, ...scenarios] = process.argv.slice(2);
  if (!repository || !scratch || !baselineRevision || !scenarios.length)
    throw Error(
      "usage: differential.ts <repository> <empty-scratch> <baseline-commit> <scenario.json>...",
    );
  await compareBuilds({ repository, scratch, baselineRevision, scenarios });
}

