const observed = <T>(value: T, evidence: FixtureEvidence[]): FixtureObservation<T> => ({
  state: "observed",
  value,
  evidence,
});
const ref = (path: string, pointer: string, detail: string): FixtureEvidence => ({
  path,
  pointer,
  detail,
