            key === name &&
            (nonempty(entry) || (typeof entry === "number" && Number.isFinite(entry)))
          )
            values.set(canonical(entry), {
              value: entry,
              evidence: ref(
                path,
                next,
                "Literal serialized " + name + "; not inferred from a filename or production rule.",
              ),
            });
          walk(entry, next);
        }
