}

/** Associates inert, byte-checked inputs. It never opens a file or computes expected game results. */
export function describeFixtureCohorts(
  inputs: { originPath: string; sha256: string; bytes: number; value: unknown; script: boolean }[],
): Pick<FixtureManifest, "files" | "suites"> {
  const loaded: LoadedFixture[] = inputs.map((input) => {
    if (
      !publicFixturePath(input.originPath) ||
      !hash(input.sha256) ||
      !Number.isSafeInteger(input.bytes) ||
      input.bytes < 0
    )
      fail("input_identity");
    const file = {
      originPath: input.originPath,
      currentPath: input.originPath,
      sha256: input.sha256,
      bytes: input.bytes,
      currentSha256: input.sha256,
      currentBytes: input.bytes,
      owner: ownerFor(input.originPath),
      kind: classify(input.value, input.script),
      suiteId: suiteIdFor(input.originPath),
    } as FixtureArtifact;
    file.metadata = literalMetadata(file, input.value);
    return { file, value: input.value };
  });
  const gods = loaded.filter((item) => item.file.kind === "god-replay"),
    eventIndex = new Map<string, Set<LoadedFixture>>();
  for (const god of gods) {
    if (!record(god.value) || !Array.isArray(god.value.events)) continue;
    for (const event of god.value.events)
      if (record(event) && typeof event.timestamp === "string" && typeof event.type === "string") {
        const key = canonical([event.timestamp, event.type, event.payload]);
        const entries = eventIndex.get(key) ?? new Set<LoadedFixture>();
        entries.add(god);
        eventIndex.set(key, entries);
      }
  }
  const groups = new Map<LoadedFixture, LoadedFixture[]>(),
    memberships = new Map<LoadedFixture, FixtureSuite["membership"][number]>();
  for (const god of gods) groups.set(god, [god]);
  for (const item of loaded) {
    let candidates: LoadedFixture[] = [],
      detail = "Standalone artifact; no cross-file relationship was asserted.";
    if (["player-view", "player-view-bundle"].includes(item.file.kind)) {
      const views = Array.isArray(item.value) ? item.value : [item.value];
      let shared: Set<LoadedFixture> | undefined;
      for (const view of views) {
        const hits = new Set<LoadedFixture>();
        if (record(view) && Array.isArray(view.timeline))
          for (const entry of view.timeline)
            if (record(entry) && record(entry.event)) {
              for (const god of eventIndex.get(
                canonical([entry.timestamp, entry.event.type, entry.event.payload]),
              ) ?? [])
                hits.add(god);
            }
        shared = shared === undefined ? hits : new Set([...shared].filter((god) => hits.has(god)));
      }
      candidates = [...(shared ?? [])].filter((god) => {
        if (
          god.file.owner !== item.file.owner ||
          god.file.metadata.actors.state !== "observed" ||
          item.file.metadata.actors.state !== "observed"
        )
          return false;
        const roster = god.file.metadata.actors.value;
        return (
          item.file.metadata.actors.value.length === views.length &&
          item.file.metadata.actors.value.every((actor) =>
            roster.some((candidate) => canonical(candidate) === canonical(actor)),
          ) &&
          views.every(
            (view) =>
              record(view) &&
              (view.locale === undefined ||
                (god.file.metadata.locale.state === "observed" &&
                  view.locale === god.file.metadata.locale.value)),
          )
        );
      });
      detail =
        "Each actor shares literal event timestamp, type and payload with exactly one god archive; actor id/role/camp and recorded locale agree. No filename or production projection supplies the match.";
    } else if (item.file.kind === "checkpoint" && record(item.value)) {
      const name = item.file.originPath.slice(item.file.originPath.lastIndexOf("/") + 1);
      const stem = name.endsWith(".checkpoint.txt")
        ? name.slice(0, -".checkpoint.txt".length)
        : name.endsWith(".json")
          ? name.slice(0, -".json".length)
          : "";
      const checkpoint = item.value;
      candidates = gods.filter((god) => {
        if (
          god.file.owner !== item.file.owner ||
          !god.file.originPath.endsWith("/" + stem + ".replay.json") ||
          !record(god.value) ||
          !record(checkpoint.snapshot) ||
          !Array.isArray(god.value.events) ||
          !record(god.value.result)
        )
          return false;
        const completeRoster = (member: LoadedFixture) =>
          record(member.value) &&
          Array.isArray(member.value.players) &&
          member.file.metadata.actors.state === "observed" &&
          member.file.metadata.actors.value.length > 0 &&
          member.file.metadata.actors.value.length === member.value.players.length &&
          new Set(member.file.metadata.actors.value.map((actor) => actor.playerId)).size ===
            member.value.players.length;
        if (!completeRoster(item) || !completeRoster(god)) return false;
        if (
          checkpoint.eventCount !== god.value.events.length ||
          canonical(
            item.file.metadata.actors.state === "observed" ? item.file.metadata.actors.value : [],
          ) !==
            canonical(
              god.file.metadata.actors.state === "observed" ? god.file.metadata.actors.value : [],
            )
        )
          return false;
        const outcome = god.value.result.decision ?? god.value.result;
        const ordinary = canonical(checkpoint.snapshot.result) === canonical(outcome);
        const last = god.value.events.at(-1);
        const failed =
          record(checkpoint.failure) &&
          checkpoint.failure.code === "cycle_failed" &&
          checkpoint.snapshot.result === null &&
          checkpoint.snapshot.gameOver === false &&
          checkpoint.complete === false &&
          god.value.result.reason === "runtime_error" &&
          god.value.result.winner === null &&
          record(last) &&
          checkpoint.snapshot.day === last.day &&
          checkpoint.snapshot.phase === last.phase;
        return ordinary || failed;
      });
      detail =
        "Basename only locates candidates; recorded eventCount, complete actor roster and literal terminal result agree, or the explicit cycle_failed/runtime_error nonterminal snapshot and last event day/phase agree. This compares archives and never predicts a rule outcome.";
    }
    const anchor =
      item.file.kind === "god-replay" ? item : candidates.length === 1 ? candidates[0]! : item;
    item.file.suiteId = suiteIdFor(anchor.file.originPath);
    if (anchor !== item) groups.get(anchor)!.push(item);
    else if (!groups.has(item)) groups.set(item, [item]);
    memberships.set(item, {
      originPath: item.file.originPath,
      state: anchor !== item ? "literal-associated" : "standalone",
      evidence: [
        ref(
          item.file.originPath,
          "",
          anchor !== item
            ? detail
            : candidates.length > 1
              ? "Multiple archive associations require review; no match was selected."
              : item.file.kind === "checkpoint"
                ? "No complete literal actor/event/outcome archive association was established; this checkpoint remains standalone pending review."
                : ["player-view", "player-view-bundle"].includes(item.file.kind)
                  ? "No unique literal event/actor/locale archive association was established; this player archive remains standalone pending review."
                  : "Standalone identity anchor; no cross-file relationship was asserted.",
        ),
      ],
    });
  }
  const suites = [...groups.entries()].map(([anchor, members]): FixtureSuite => {
    const metadata = mergeMetadata(anchor, members);
    const unresolved = Object.entries(metadata).flatMap(([name, observation]) =>
      observation.state === "unknown" ? [name + ": " + observation.reason] : [],
    );
    if (
      anchor.file.kind === "player-view" ||
      anchor.file.kind === "player-view-bundle" ||
      anchor.file.kind === "unknown-json"
    )
      unresolved.push("Archive association is unresolved; this artifact remains standalone.");
    unresolved.push(
      "Grouping and exact byte preservation are inventory evidence; independent scenario/consumer acceptance has not been assigned.",
    );
    return {
      suiteId: suiteIdFor(anchor.file.originPath),
      anchorOriginPath: anchor.file.originPath,
      owner: anchor.file.owner,
      kind:
        anchor.file.kind === "god-replay"
          ? "recorded-archive"
          : anchor.file.kind === "adapter-script"
            ? "adapter-script"
            : "unassociated-json",
      files: members.map((member) => member.file.originPath).sort(),
      metadata,
      membership: members
        .map((member) => memberships.get(member)!)
        .sort((a, b) => a.originPath.localeCompare(b.originPath)),
      acceptance: {
        status: "pending-review",
        evidence: [
          {
            kind: "metadata-association",
            reference: anchor.file.originPath,
            detail:
              "Membership evidence identifies literal associations or explicit standalone status; this pure description does not verify caller-supplied byte hashes or infer passed test status.",
          },
        ],
        unresolved,
      },
    };
  });
  return {
    files: loaded.map((item) => item.file).sort((a, b) => a.originPath.localeCompare(b.originPath)),
    suites: suites.sort((a, b) => a.suiteId.localeCompare(b.suiteId)),
  };
}

/** Derives an exact registered subset; this does not read disk or assign acceptance. */
export function deriveLocalFixtureManifest(
  document: FixtureManifest,
  manifestPath: string,
): FixtureManifest {
  const descriptor = document.derivedManifests.find((entry) => entry.path === manifestPath);
  if (!descriptor) fail("derived_manifest_unregistered");
  const suites = document.suites.filter((suite) => descriptor.suiteIds.includes(suite.suiteId));
  const origins = new Set(suites.flatMap((suite) => suite.files));
  const files = document.files.filter((file) => origins.has(file.originPath));
  const exactBytesFiles = files.filter(
    (file) => file.sha256 === file.currentSha256 && file.bytes === file.currentBytes,
  ).length;
  return parseFixtureManifest(
    JSON.stringify({
      ...document,
      files,
      suites,
      derivedManifests: [],
      sourceAssets: document.sourceAssets.filter(
        (asset) => asset.kind === "test-support" || origins.has(asset.originPath),
      ),
      coverage: {
        expectedFiles: files.length,
        exactBytesFiles,
        mechanicalSourceFiles: files.length - exactBytesFiles,
        originalBytes: files.reduce((sum, file) => sum + file.bytes, 0),
        currentBytes: files.reduce((sum, file) => sum + file.currentBytes, 0),
      },
    }),
  );
}

/** Compares detached source programs, including RPC/action literals and imported bindings. Only approved source path rebasing and leading trivia are normalized; input scripts are never executed. */
export function sourceProgramContract(
  ts: typeof import("typescript"),
  text: string,
  filename: string,
  current: boolean,
  mappings: readonly { originPath: string; currentPath: string }[],
  relocations: readonly FixtureSourceModuleRelocation[] = [],
): { statements: string[]; moduleBindings: string[] } {
  const inverse = new Map(mappings.map((asset) => [asset.currentPath, asset.originPath]));
  const relocated = new Map(relocations.map((entry) => [entry.currentPath, entry]));
  const observedRelocations = new Set<string>();
  const ast = ts.createSourceFile(filename, text, ts.ScriptTarget.Latest, true);
  const changes: { start: number; end: number; replacement: string }[] = [];
  const imports: string[] = [];
  const visit = (node: import("typescript").Node) => {
    let literal: import("typescript").StringLiteralLike | undefined;
    if (
      (ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) &&
      node.moduleSpecifier &&
      ts.isStringLiteralLike(node.moduleSpecifier)
    )
      literal = node.moduleSpecifier;
    else if (
      ts.isImportTypeNode(node) &&
      ts.isLiteralTypeNode(node.argument) &&
      ts.isStringLiteralLike(node.argument.literal)
    )
      literal = node.argument.literal;
    else if (
      ts.isCallExpression(node) &&
      node.expression.kind === ts.SyntaxKind.ImportKeyword &&
      node.arguments[0] &&
      ts.isStringLiteralLike(node.arguments[0])
    )
      literal = node.arguments[0];
    if (literal) {
      let identity = literal.text;
      if (identity.startsWith(".")) {
        identity = normalizeSourceModule(filename, identity);
        if (!identity.endsWith(".ts")) identity += ".ts";
        if (current) {
          const relocation = relocated.get(identity);
          if (relocation) {
            if (!ts.isImportDeclaration(node) || !node.importClause || node.importClause.name ||
              !node.importClause.namedBindings || !ts.isNamedImports(node.importClause.namedBindings))
              fail("source_module_relocation_requires_named_import");
            const names = node.importClause.namedBindings.elements.map((entry) =>
              (entry.propertyName ?? entry.name).text).sort();
            const expected = relocation.bindings.map((entry) => entry.name).sort();
            if (JSON.stringify(names) !== JSON.stringify(expected))
              fail("source_module_relocation_binding_drift");
            if (observedRelocations.has(identity)) fail("source_module_relocation_duplicate_import");
            observedRelocations.add(identity);
            identity = relocation.originPath;
          }
          identity = inverse.get(identity) ?? identity;
        }
      }
      changes.push({
        start: literal.getStart(ast),
        end: literal.getEnd(),
        replacement: JSON.stringify(identity),
      });
      imports.push(node.getText(ast).replace(literal.getText(ast), JSON.stringify(identity)));
    }
    ts.forEachChild(node, visit);
  };
  visit(ast);
  if (current && observedRelocations.size !== relocations.length)
    fail("source_module_relocation_unused");
  let normalized = text;
  for (const change of changes.sort((a, b) => b.start - a.start))
    normalized =
      normalized.slice(0, change.start) + change.replacement + normalized.slice(change.end);
  const normalizedAst = ts.createSourceFile(filename, normalized, ts.ScriptTarget.Latest, true);
  return {
    statements: normalizedAst.statements.map((node) => node.getText(normalizedAst)),
    moduleBindings: imports,
  };
}

/** Complete named declaration syntax, without formatting/comments or executing source. */
export function sourceDeclarationContract(
  ts: typeof import("typescript"), text: string, filename: string, name: string,
): string {
  const ast = ts.createSourceFile(filename, text, ts.ScriptTarget.Latest, true);
  const nodes = ast.statements.filter((node) => {
    if (ts.isFunctionDeclaration(node) || ts.isInterfaceDeclaration(node) ||
      ts.isTypeAliasDeclaration(node) || ts.isClassDeclaration(node) || ts.isEnumDeclaration(node))
      return node.name?.text === name;
    return false;
  });
  if (nodes.length !== 1) fail("source_module_declaration_identity");
  const declaration = nodes[0]!;
  const modifiers = ts.canHaveModifiers(declaration) ? ts.getModifiers(declaration) : undefined;
  if (!modifiers?.some((modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword) ||
    modifiers.some((modifier) => modifier.kind === ts.SyntaxKind.DefaultKeyword))
    fail("source_module_declaration_requires_named_export");
  return ts.createPrinter({ removeComments: true, newLine: ts.NewLineKind.LineFeed })
    .printNode(ts.EmitHint.Unspecified, declaration, ast);
}

function normalizeSourceModule(filename: string, specifier: string): string {
  const parts = (filename.slice(0, filename.lastIndexOf("/") + 1) + specifier).split("/");
  const normalized: string[] = [];
  for (const part of parts) {
    if (part === "." || !part) continue;
    if (part === "..") normalized.pop();
    else normalized.push(part);
  }
  return normalized.join("/");
}

/** Checks recorded metadata against detached archive inputs; neither side computes game-rule expectations. */
export function assertLiteralFixtureMetadata(
  layout: FixtureManifest,
  actualInputs: Parameters<typeof describeFixtureCohorts>[0],
): void {
  const described = describeFixtureCohorts(actualInputs);
  const fileMetadata = (files: FixtureArtifact[]) =>
    files.map(({ originPath, kind, suiteId, metadata }) => ({
      originPath,
      kind,
      suiteId,
      metadata,
    }));
  const suiteMetadata = (suites: FixtureSuite[]) =>
    suites.map(({ suiteId, anchorOriginPath, owner, kind, files, metadata, membership }) => ({
      suiteId,
      anchorOriginPath,
      owner,
      kind,
      files,
      metadata,
      membership,
    }));
  if (
    canonical(fileMetadata(described.files)) !== canonical(fileMetadata(layout.files)) ||
    canonical(suiteMetadata(described.suites)) !== canonical(suiteMetadata(layout.suites))
  )
    fail("literal_archive_metadata_or_association_drift");
}

/** Reads only allowlisted public fixture roots and verifies immutable Git bytes before describing them. */
export async function generateFixtureManifest(repository: string): Promise<FixtureManifest> {
  const fs = await import("node:fs/promises"),
    path = await import("node:path"),
    crypto = await import("node:crypto"),
    childProcess = await import("node:child_process");
  const requestedRoot = path.resolve(repository);
  const rootParts = requestedRoot
    .slice(path.parse(requestedRoot).root.length)
    .split(path.sep)
    .filter(Boolean);
  if (rootParts.some(privateSegment)) fail("private_repository_path_rejected");
  let rootComponent = path.parse(requestedRoot).root;
  for (const part of rootParts) {
    rootComponent = path.join(rootComponent, part);
    const info = await fs.lstat(rootComponent);
    if (info.isSymbolicLink()) fail("repository_symlink_rejected");
    if (!info.isDirectory()) fail("repository_directory_required");
  }
  const root = await fs.realpath(requestedRoot);
  if (root !== requestedRoot) fail("repository_resolution_changed");
  const digest = (bytes: Uint8Array | string) =>
    crypto.createHash("sha256").update(bytes).digest("hex");
  async function safeFile(relative: string) {
    if (
      relative !== inventoryPath &&
      relative !== fixtureManifestPath &&
      !publicFixturePath(relative) &&
      !publicSupportSourcePath(relative)
    )
      fail("private_path_rejected");
    const parts = relative.split("/");
    for (let index = 1; index <= parts.length; index++) {
      const candidate = path.join(root, ...parts.slice(0, index)),
        info = await fs.lstat(candidate);
      if (info.isSymbolicLink()) fail("symlink_rejected");
      if (
        (index < parts.length && !info.isDirectory()) ||
        (index === parts.length && !info.isFile())
      )
        fail("public_input_kind");
    }
    return fs.readFile(path.join(root, relative));
  }
  const inventoryBytes = await safeFile(inventoryPath),
    inventory: unknown = JSON.parse(inventoryBytes.toString("utf8"));
  if (!record(inventory) || inventory.commit !== baselineCommit || !Array.isArray(inventory.files))
    fail("frozen_inventory_identity");
  const rows = inventory.files.map((row: unknown) => {
    if (
      !record(row) ||
      !publicFixturePath(row.path) ||
      !hash(row.sha256) ||
      !Number.isSafeInteger(row.bytes) ||
      Number(row.bytes) < 0
    )
      fail("frozen_inventory_row");
    return { originPath: row.path, sha256: row.sha256, bytes: Number(row.bytes) };
  });
  const git = childProcess.execFileSync(
    "git",
    ["ls-tree", "-r", "-z", baselineCommit, "--", ...fixtureRoots],
    { cwd: root, encoding: "utf8", maxBuffer: 4 * 1024 * 1024 },
  );
  const origin = git
    .split("\0")
    .filter(Boolean)
    .map((entry) => {
      const match = /^(\d+) blob ([a-f0-9]{40})\t(.+)$/.exec(entry);
      if (!match || match[1] === "120000" || !publicFixturePath(match[3])) fail("frozen_git_input");
      return { path: match[3]!, blob: match[2]! };
    });
  if (
    origin.length !== 907 ||
    rows.length !== origin.length ||
    new Set(rows.map((row) => row.originPath)).size !== rows.length ||
    rows.some((row) => !origin.some((entry) => entry.path === row.originPath))
  )
    fail("frozen_inventory_coverage");
  const blobs = childProcess.execFileSync("git", ["cat-file", "--batch"], {
    cwd: root,
    input: origin.map((entry) => entry.blob).join("\n") + "\n",
    maxBuffer: 128 * 1024 * 1024,
  });
  const originalContents = new Map<string, Uint8Array>();
  let offset = 0;
  for (const entry of origin) {
    const end = blobs.indexOf(10, offset),
      header = blobs.subarray(offset, end).toString("utf8"),
      match = /^([a-f0-9]{40}) blob (\d+)$/.exec(header);
    if (end < 0 || !match || match[1] !== entry.blob) fail("frozen_git_blob");
    const size = Number(match[2]),
      content = blobs.subarray(end + 1, end + 1 + size),
      row = rows.find((candidate) => candidate.originPath === entry.path)!;
    if (
      content.length !== size ||
      blobs[end + 1 + size] !== 10 ||
      size !== row.bytes ||
      digest(content) !== row.sha256
    )
      fail("frozen_inventory_blob_mismatch");
    originalContents.set(entry.path, content);
    offset = end + size + 2;
  }
  const layout = parseFixtureManifest((await safeFile(fixtureManifestPath)).toString("utf8"));
  if (
    layout.files.length !== rows.length ||
    rows.some(
      (row) =>
        !layout.files.some(
          (file) =>
            file.originPath === row.originPath &&
            file.sha256 === row.sha256 &&
            file.bytes === row.bytes,
        ),
    )
  )
    fail("layout_original_coverage");
  const { compiler } = await import("./architecture/contracts");
  const ts = compiler(root);
  function program(text: string, filename: string, current: boolean, relocations: FixtureSourceModuleRelocation[] = []) {
    const contract = sourceProgramContract(ts, text, filename, current, layout.sourceAssets, relocations);
    return {
      programSha256: digest(JSON.stringify(contract.statements)),
      moduleBindingsSha256: digest(JSON.stringify(contract.moduleBindings)),
    };
  }
  for (const asset of layout.sourceAssets) {
    const original =
      originalContents.get(asset.originPath) ??
      childProcess.execFileSync("git", ["show", `${asset.originCommit}:${asset.originPath}`], {
        cwd: root,
        maxBuffer: 4 * 1024 * 1024,
      });
    const current = await safeFile(asset.currentPath);
    if (
      digest(original) !== asset.originalSha256 ||
      original.length !== asset.originalBytes ||
      digest(current) !== asset.currentSha256 ||
      current.length !== asset.currentBytes
    )
      fail("source_asset_byte_identity");
    for (const relocation of asset.moduleRelocations ?? []) {
      const previous = childProcess.execFileSync("git", ["show", `${relocation.originCommit}:${relocation.originPath}`], {
        cwd: root, maxBuffer: 4 * 1024 * 1024,
      }).toString("utf8");
      const moved = (await safeFile(relocation.currentPath)).toString("utf8");
      for (const binding of relocation.bindings) {
        const before = digest(sourceDeclarationContract(ts, previous, relocation.originPath, binding.name));
        const after = digest(sourceDeclarationContract(ts, moved, relocation.currentPath, binding.name));
        if (before !== binding.declarationSha256 || after !== before)
          fail("source_module_relocation_declaration_drift");
      }
    }
    const before = program(Buffer.from(original).toString("utf8"), asset.originPath, false),
      after = program(current.toString("utf8"), asset.currentPath, true, asset.moduleRelocations);
    if (
      before.programSha256 !== after.programSha256 ||
      before.moduleBindingsSha256 !== after.moduleBindingsSha256 ||
      before.programSha256 !== asset.programSha256 ||
      before.moduleBindingsSha256 !== asset.moduleBindingsSha256
    )
      fail("source_asset_program_or_import_drift");
  }
  const currentPaths: string[] = [];
  async function scan(relative: string) {
    const info = await fs.lstat(path.join(root, relative));
    if (info.isSymbolicLink()) fail("symlink_rejected");
    if (info.isDirectory())
      for (const name of (await fs.readdir(path.join(root, relative))).sort())
        await scan(relative + "/" + name);
    else if (info.isFile() && publicFixturePath(relative)) currentPaths.push(relative);
    else fail("unexpected_fixture_kind");
  }
  for (const directory of fixtureRoots) {
    // lstat of a whole path can follow an earlier component; verify each public
    // directory ancestor before recursion is allowed to enumerate any children.
    const parts = directory.split("/");
    for (let index = 1; index <= parts.length; index++) {
      const info = await fs.lstat(path.join(root, ...parts.slice(0, index)));
      if (info.isSymbolicLink()) fail("symlink_rejected");
      if (!info.isDirectory()) fail("public_fixture_directory_required");
    }
    await scan(directory);
  }
  const expectedPaths = new Set([
    ...layout.files.map((file) => file.currentPath),
    ...layout.derivedManifests.map((entry) => entry.path),
  ]);
  if (
    currentPaths.length !== expectedPaths.size ||
    currentPaths.some((file) => !expectedPaths.has(file))
  )
    fail("current_fixture_coverage");
  const actualInputs = [];
  for (const file of layout.files) {
    const bytes = await safeFile(file.currentPath);
    if (digest(bytes) !== file.currentSha256 || bytes.length !== file.currentBytes)
      fail("current_fixture_byte_drift");
    if (
      file.kind !== "adapter-script" &&
      (digest(bytes) !== file.sha256 || bytes.length !== file.bytes)
    )
      fail("json_archive_byte_drift");
    actualInputs.push({
      originPath: file.originPath,
      sha256: file.sha256,
      bytes: file.bytes,
      script: file.kind === "adapter-script",
      value:
        file.kind === "adapter-script"
          ? undefined
          : (JSON.parse(bytes.toString("utf8")) as unknown),
    });
  }
  assertLiteralFixtureMetadata(layout, actualInputs);
  for (const derived of layout.derivedManifests) {
    const subset = deriveLocalFixtureManifest(layout, derived.path);
    const actual = parseFixtureManifest((await safeFile(derived.path)).toString("utf8"));
    if (canonical(subset) !== canonical(actual)) fail("derived_manifest_content_drift");
  }
  return layout;
}

