/**
 * 负责定义结构门禁的输入、诊断、债务与报告数据，并提供摘要和源码解析辅助。
 * 输入为调用方捕获的公共源码文本、路径和 SHA；输出保留原记录结构、摘要与解析结果。
 * 这些契约由本模块拥有，不包含游戏状态、资源写权或行动许可；字段声明不复制或冻结输入。
 * 原债务只由固定基线生成入口产生，检查不更新基线；调用方仍须验证捕获字节与 SHA 的对应关系。
 * AST 与词项检查不能证明职责说明真实，实际所有权、异常和时序仍需人工审查。
 */
import { createHash } from "node:crypto";
import { createRequire } from "node:module";
import path from "node:path";
import type * as TypeScript from "typescript";

/** 捕获方负责让文本和摘要来自同一真实输入；检查库消费这三个字段，不自行重算文本摘要。 */
export interface ArchitectureFile {
  path: string;
  text: string;
  sha256: string;
}
export interface ArchitectureInput {
  files: ArchitectureFile[];
  documentationPaths: string[];
}
export interface ArchitectureViolation {
  id: string;
  rule: string;
  path: string;
  line: number;
  column: number;
  detail: string;
  target?: string;
  specifier?: string;
  binding?: string;
}
export interface ArchitectureDebt {
  schema: "awa-architecture-debt-v1";
  generatedBy: "tooling/refactor/architecture/run.ts";
  baselineCommit: string;
  baselineInputHash: string;
  files: { path: string; sha256: string }[];
  violations: ArchitectureViolation[];
  policy: string;
}
export interface PathMapping {
  from: string;
  to: string;
  reason: string;
}
export interface ArchitectureReport {
  schema: "awa-architecture-report-v1";
  inputHash: string;
  failures: ArchitectureViolation[];
  remainingDebt: ArchitectureViolation[];
  clearedDebt: string[];
  counts: {
    files: number;
    violations: number;
    failures: number;
    remainingDebt: number;
    clearedDebt: number;
  };
  policy: string;
}
export const digest = (value: Uint8Array | string) =>
  createHash("sha256").update(value).digest("hex");
/** 只摘要排序后的路径／已提供 SHA 元信息；不读取文件或重算 text，也不是对局 Tape 的 sourceHash。 */
export const sourceDigest = (files: ArchitectureFile[]) =>
  digest(
    JSON.stringify(
      [...files]
        .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
        .map(({ path, sha256 }) => ({ path, sha256 })),
    ),
  );
// 诊断身份由规则、路径和业务身份组成；行列仅用于定位，位置移动不自动制造一项新债务。
export function violation(
  rule: string,
  file: string,
  line: number,
  column: number,
  detail: string,
  identity = detail,
  extra?: Pick<ArchitectureViolation, "target" | "specifier" | "binding">,
): ArchitectureViolation {
  return {
    id: digest(`${rule}\0${file}\0${identity}`),
    rule,
    path: file,
    line,
    column,
    detail,
    ...extra,
  };
}
export function compiler(repository: string): typeof TypeScript {
  return createRequire(path.join(path.resolve(repository), "backend/package.json"))(
    "typescript",
  ) as typeof TypeScript;
}
export function parseSource(ts: typeof TypeScript, file: ArchitectureFile): TypeScript.SourceFile {
  return ts.createSourceFile(
    file.path,
    file.text,
    ts.ScriptTarget.Latest,
    true,
    /\.[jt]sx$/.test(file.path)
      ? ts.ScriptKind.TSX
      : /\.[cm]?js$/.test(file.path)
        ? ts.ScriptKind.JS
        : ts.ScriptKind.TS,
  );
}
export function isProductionPath(file: string): boolean {
  return /^(?:backend\/src\/|frontend\/src\/|packages\/[^/]+\/src\/)/.test(file);
}
export function isTypedSource(file: string): boolean {
  return /\.[cm]?[jt]sx?$/.test(file);
}

/**
 * 负责检查首个源码语句之前的第一份有效职责说明。输入为 JS／TS 文本和公开文档路径名；
 * 输出为缺头、占位、类别字段或已知链接目标违规，不按注释数量判验收。
 * 检查只核 AST／注释位置与职责词项形状；真实写权、失败政策、生命周期和说明内容仍须独立人工审查。
 * 这里不执行源码、不读取文档内容或授予任何业务权限，语法合格的职责头不等于完整架构或玩法验收。
 */
import path from "node:path";
import type * as TypeScript from "typescript";
import {
  isTypedSource,
  parseSource,
  violation,
  type ArchitectureInput,
  type ArchitectureViolation,
} from "./contracts";

type Category = "behavior" | "test" | "data" | "lifecycle" | "adapter" | "exports" | "hook";
// 类别按原路径优先级决定，测试／生命周期等先匹配；不依据正文猜模块职责或改变规则。
export function commentCategory(file: string): Category {
  if (/\.(?:test|spec)\.[cm]?[jt]sx?$/.test(file) || /\/tests\/(?:support|fixtures)\//.test(file))
    return "test";
  if (
    /\/(?:authority|lifecycle|requests|lease|request_envelope|request_delivery|session_pool|session_lifecycle)\.[cm]?[jt]s$/.test(
      file,
    )
  )
    return "lifecycle";
  if (/\/(?:integrations|adapters)\//.test(file)) return "adapter";
  if (/\/(?:contracts|[^/]*schema|[^/]*state|[^/]*types)\.[cm]?[jt]s$/.test(file)) return "data";
  if (/\/index\.[cm]?[jt]s$/.test(file)) return "exports";
  if (/\/hooks?\/|\/(?:ports|[^/]*hook)\.[cm]?[jt]s$/.test(file)) return "hook";
  return "behavior";
}
const concepts = {
  responsibility:
    /responsib|own|provid|manag|implement|compar|freez|inventor|check|validat|verif|\btests?\b|define|describ|expos|derive|record|project|adapt|collect|build|generat|load|read|orchestrat|render|parse|负责|提供|实现|管理|校验|验证|盘点|整理|建立|解析|渲染/i,
  input: /\binputs?\b|\bfrom\b|receiv|accept|输入|接收|来源|从|消费/i,
  output:
    /\boutputs?\b|\breturn|\bresult|\bproduc|\bemit|\bwrite|\bexport|输出|返回|产生|发布|生成|导出|写入/i,
  boundary:
    /boundar|\bonly\b|\bnever\b|\bwithout\b|\bnot\b|\bno\b|separat|边界|不|仅|只|禁止|独立|协作/i,
  owner: /\bowner|\bowns?\b|owned|权威|所属|所有者|拥有|负责/i,
  structure: /structur|\bdata\b|\bschema\b|\brecord|\bcontract|数据|结构|契约|字段|格式/i,
  layer: /\bunit\b|integration|scenario|architecture|\btest|测试|单元|集成|场景|验证层级/i,
  oracle: /oracle|fixture|literal|expect|independent|断言|预期|字面|独立|来源|样本/i,
  write: /\bwrite|\bmutat|\bcommit|\bcreate|\bclose|\bown|写权|写入|修改|提交|创建|关闭|所有者/i,
  invariant: /invariant|\bonly\b|\bmust\b|\bnever\b|monoton|不变量|必须|始终|单调|仅|禁止/i,
  terminal:
    /terminal|fail|cancel|abort|retir|withdraw|closed|stop|终态|失败|取消|撤权|关闭|中止|失效/i,
  sideEffect:
    /side.effect|\bprocess|\bnetwork|\btransport|\bfile|\bprotocol|\bsession|副作用|进程|网络|传输|文件|协议|会话/i,
  deadline: /deadline|budget|timeout|期限|预算|超时/i,
  cancellation: /cancel|\bclose|reclaim|取消|关闭|回收/i,
  consumer: /consumer|consum|\bpublic|\bbackend|\bfrontend|调用方|消费者|消费|公开|前端|后端/i,
  timing: /timing|\bwhen\b|\bbefore\b|\bafter\b|\border\b|时点|顺序|之前|之后|何时/i,
  permission: /permission|\bread|\bwrite|\bmutat|允许|权限|读|写|修改/i,
};
const required: Record<Category, (keyof typeof concepts)[]> = {
  behavior: ["responsibility", "input", "output", "boundary"],
  test: ["responsibility", "layer", "oracle"],
  data: ["responsibility", "owner", "structure", "boundary"],
  lifecycle: ["responsibility", "owner", "write", "invariant", "terminal"],
  adapter: ["responsibility", "sideEffect", "deadline", "cancellation", "boundary"],
  exports: ["consumer", "output", "boundary"],
  hook: ["responsibility", "timing", "input", "permission", "terminal"],
};
// 许可证、引用和工具指令不作为职责说明；保留原识别范围，不把后续好注释用来掩盖首个占位头。
const nonSubstantive = (text: string) => {
  const content = text
    .replace(/^\s*\/\*[*!]?|\*\/\s*$/g, "")
    .split("\n")
    .map((line) => line.replace(/^\s*(?:\*|\/\/\/?)\s?/, ""))
    .join("\n")
    .trim();
  return /^(?:<reference|@(?:ts-|jsx|license)|copyright\b|SPDX\b|licensed\b|license\b|eslint\b|prettier\b|noinspection\b|vite\b|istanbul\b|c8\b)/i.test(
    content,
  );
};

export function checkComments(
  ts: typeof TypeScript,
  input: ArchitectureInput,
): ArchitectureViolation[] {
  const failures: ArchitectureViolation[] = [],
    publicFiles = new Set([...input.files.map((file) => file.path), ...input.documentationPaths]);
  for (const file of input.files.filter((entry) => isTypedSource(entry.path))) {
    const source = parseSource(ts, file),
      first = source.statements[0],
      boundary = first?.getStart(source) ?? file.text.length;
    const scanner = ts.createScanner(
      ts.ScriptTarget.Latest,
      false,
      ts.LanguageVariant.Standard,
      file.text,
    );
    let header: { start: number; end: number; text: string } | undefined;
    for (
      let token = scanner.scan();
      token !== ts.SyntaxKind.EndOfFileToken && scanner.getTokenPos() < boundary;
      token = scanner.scan()
    ) {
      if (
        token !== ts.SyntaxKind.SingleLineCommentTrivia &&
        token !== ts.SyntaxKind.MultiLineCommentTrivia
      )
        continue;
      const text = scanner.getTokenText();
      if (nonSubstantive(text)) continue;
      const start = scanner.getTokenPos();
      if (token === ts.SyntaxKind.SingleLineCommentTrivia) {
        const remainder = file.text.slice(start, boundary),
          lines = remainder.split("\n"),
          collected: string[] = [];
        for (const line of lines) {
          if (!/^\s*\/\//.test(line)) break;
          collected.push(line);
        }
        header = { start, end: start + collected.join("\n").length, text: collected.join("\n") };
      } else header = { start, end: scanner.getTextPos(), text };
      break;
    }
    // scanner 只寻找首语句前的首份有效说明；后面的内容不能替代这一已选职责头。
    const category = commentCategory(file.path),
      pos = source.getLineAndCharacterOfPosition(header?.start ?? boundary);
    const add = (rule: string, detail: string, identity: string = category) =>
      failures.push(violation(rule, file.path, pos.line + 1, pos.character + 1, detail, identity));
    if (!header) {
      add(
        "comment.missing-head",
        `Missing ${category} responsibility contract before first business statement.`,
      );
      continue;
    }
    const text = header.text
      .replace(/^\s*\/\*\*?|\*\/\s*$/g, "")
      .split("\n")
      .map((line) => line.replace(/^\s*(?:\*|\/\/)\s?/, ""))
      .join("\n")
      .trim();
    if (
      !text ||
      /本文件相关逻辑|角色相关代码|负责.*相关(?:逻辑|代码)|this file handles (?:things|logic)|\bTODO\b|\bTBD\b/i.test(
        text,
      )
    ) {
      add("comment.placeholder", "Responsibility head is empty or uses placeholder language.");
      continue;
    }
    const firstParagraph = text.split(/\n\s*\n/)[0] ?? "";
    if (!concepts.responsibility.test(firstParagraph) && category !== "exports")
      add("comment.first-paragraph", "First substantive paragraph does not name a responsibility.");
    for (const field of required[category])
      if (!concepts[field].test(text))
        add(
          `comment.${field}`,
          `${category} head lacks its ${field} contract.`,
          `${category}:${field}`,
        );
    const links = [
      ...[...text.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)].map((match) => ({
        target: match[1]!,
        rootRelative: match[1]!.startsWith("docs/"),
      })),
      ...[
        ...text.matchAll(
          /(?:^|[\s`(])((?:docs\/|\.{1,2}\/|\/(?:docs|backend|frontend|packages)\/)[a-zA-Z0-9_./-]+\.md(?:#[a-zA-Z0-9_-]+)?)/gm,
        ),
      ].map((match) => ({ target: match[1]!, rootRelative: match[1]!.startsWith("docs/") })),
    ];
    // 链接只核调用方给定的公共文件／文档路径集合；去掉 fragment，不在此验证实际锚点或文档语义。
    for (const link of [...new Map(links.map((link) => [link.target, link])).values()]) {
      const target = link.target.replace(/^<|>$/g, "").split("#")[0]!;
      if (!target || /^(?:https?:|mailto:)/.test(target)) continue;
      const resolved = link.rootRelative
        ? target
        : target.startsWith("/")
          ? target.slice(1)
          : path.posix.normalize(path.posix.join(path.posix.dirname(file.path), target));
      if (!publicFiles.has(resolved))
        add(
          "comment.broken-link",
          "Responsibility contract link does not point to a known public file.",
          `${category}:${target}`,
        );
    }
  }
  return failures;
}

/**
 * 负责四种原有序协议及动态窗口协议的请求绑定与有限运行租约。输入为原请求、机制晚查询和期限别名；
 * 输出为同一 scope 引用和一次完成通知，只写本实例的请求／租约元数据，不写 World、生命或库存。
 * 各实例保独立表及稳定传播回调；同请求可多绑定，但真实窗口只打开对应一个交付 turn。
 * 原 envelope 或领域当前性观察失配永久关闭共同许可；别名自己的字段失配只退役该别名。
 * 合法期限别名共享最早绝对预算，观察到期后时钟回退也不复活。字段 pin 只保顶层原值引用，
 * 不深复制／冻结提示或 feed，不把相同 JSON、readonly 或请求字段当成领域许可。
 * Provider 返回不是付款；窗口完整付款后才 complete，状态先落再通知，晚异常不能二次结算。
 */
import type { ActionRequest } from "./actions";
import { bindRequestDeliveryGuard, registerRequestAliasPropagation, settleRequestDelivery } from "./request_delivery";

/** 仅晚读原 scope 字段／活跃表；不接受整个请求回调，字段接纳与读取次序在本 owner 中实现。 */
export interface RequestLeaseScopeQueries<Owner, Scope> {
  active(owner: Owner): Scope | undefined;
  owner(scope: Scope): Owner;
  actorId(scope: Scope): number;
  phase(): ActionRequest["phase"];
  stage(scope: Scope): ActionRequest["context"]["stage"];
}

/** 动态窗口只给出捕获值和晚领域查询；scope 是每个原请求独立的不透明对象，不由请求重建。
 * 日次／阶段不固定为首夜，明确声明的 context 字段只 pin 原值引用，不创建 World 或死亡许可。
 */
export interface RequestLeaseWindowQueries<Scope extends object> {
  actorId(scope: Scope): number;
  phase(scope: Scope): ActionRequest["phase"];
  day(scope: Scope): number;
  stage(scope: Scope): ActionRequest["context"]["stage"];
  current(scope: Scope): boolean;
}

/** current 仍调用原机制规则；不能据请求字段相同代替原体、生命和库存复验。 */
export interface RequestLeaseCurrentQueries<Owner, Scope> extends RequestLeaseScopeQueries<Owner, Scope> {
  current(scope: Scope): boolean;
}

/** 墙入口先查原作者；原 token／实例值在条件和记录构造位置各自读取，不缓存授权或复制作者。 */
export interface RequestLeaseItemQueries<Owner, Scope, Author> {
  active(owner: Owner): Scope | undefined;
  authors(scope: Scope): Pick<ReadonlyMap<number, Author>, "get">;
  token(scope: Scope): string;
  instanceId(author: Author): string;
  phase(): ActionRequest["phase"];
  stage(): ActionRequest["context"]["stage"];
  current(owner: Owner, scope: Scope, author: Author): boolean;
}

/** context 保原引用，记录不是请求 DTO；合法别名共享同一记录，不做深只读或序列化。 */
interface ScopeBinding<Scope> {
  scope: Scope;
  context: ActionRequest["context"];
}
/** context 身份和声明字段由本 owner 捕获；只保存值／引用，不序列化或深冻结整个 context。 */
interface WindowBinding<Scope> extends ScopeBinding<Scope> {
  fields: Array<{ key: string; value: unknown }>;
}
interface CurrentBinding<Scope> {
  binding: Scope;
  context: ActionRequest["context"];
}
/** 捕获墙的原 owner／作者编号与实例值；后续查询仍晚查活跃墙，不能由编号自行生成许可。 */
interface ItemBinding<Owner, Scope, Author> extends ScopeBinding<Scope> {
  author: Author;
  world: Owner;
  actorId: number;
  instanceId: string;
}

// 字段比较仍排除 deadlineAtMs；其有限未来／只能缩短的政策在比较成功后单独处理。
function sameIndexedFields(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return !(
    keys.length !== other.length ||
    keys.some((k) => !other.includes(k) || (source as any)[k] !== (target as any)[k])
  );
}
function everyIndexedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && (source as any)[k] === (target as any)[k])
  );
}
function everyReflectedField(source: ActionRequest, target: ActionRequest): boolean {
  const keys = Object.keys(source).filter((k) => k !== "deadlineAtMs"),
    other = Object.keys(target).filter((k) => k !== "deadlineAtMs");
  return (
    keys.length === other.length &&
    keys.every((k) => other.includes(k) && Reflect.get(source, k) === Reflect.get(target, k))
  );
}

/** 窗口私有的运行完成端口；不持 World/付款回调，不可由 JSON 或请求字段重建。 */
export interface RequestLeaseTurn {
  current(): boolean;
  complete(): void;
  close(): void;
}
/** pin 只核顶层枚举字段及原值引用；嵌套数据/合法 getter/Proxy 不套新 schema 或深只读政策。 */
interface FieldPin { keys: string[]; values: unknown[] }
interface LeaseTurn<Owner, Binding> {
  owner: Owner;
  original: ActionRequest;
  binding: Binding;
  pin?: FieldPin;
  originalDeadline?: unknown;
  deadline: number | null;
  closed: boolean;
  settled: boolean;
  opened: boolean;
  completion: object;
  aliases: Set<ActionRequest>;
  handle?: RequestLeaseTurn;
}
interface LeaseEntry<Owner, Binding> {
  turn: LeaseTurn<Owner, Binding>;
  retired: boolean;
  deadline: unknown;
}
function pinFields(request: ActionRequest): FieldPin {
  const keys = Object.keys(request).filter((key) => key !== "deadlineAtMs");
  return { keys, values: keys.map((key) => Reflect.get(request, key)) };
}
function samePinnedFields(request: ActionRequest, pin: FieldPin): boolean {
  const keys = Object.keys(request).filter((key) => key !== "deadlineAtMs");
  return keys.length === pin.keys.length && keys.every((key) => {
    const index = pin.keys.indexOf(key);
    return index !== -1 && Object.is(Reflect.get(request, key), pin.values[index]);
  });
}

/**
 * 每实例唯一持有请求登记；类型入口开放明确协议，实际机制接线不传完整 request callback。
 * 私有构造签名限制 typed 调用，不是运行时权限屏障；接纳算法在本 owner 内完整执行。
 * 四个旧协议保原字段短路；动态窗口显式增加字段／日次查询，外围复用 F02 政策，不建立 Role 分派或第二租约。
 */
export class RequestLease<Owner, Scope, Binding> {
  private readonly records = new WeakMap<ActionRequest, LeaseEntry<Owner, Binding>>();
  private readonly propagate = (source: ActionRequest, target: ActionRequest): void => {
    this.inherit(source, target);
  };

  private constructor(
    private readonly order: number,
    private readonly bindRequest: (owner: Owner, request: ActionRequest, lease: RequestLease<Owner, Scope, Binding>) => void,
    private readonly matches: (owner: Owner, request: ActionRequest, binding: Binding) => boolean,
    private readonly bindingOwner: (binding: Binding) => Owner,
    private readonly bindingScope: (binding: Binding) => Scope,
    private readonly sameFields: (source: ActionRequest, target: ActionRequest) => boolean,
    private readonly domainCurrent: (owner: Owner, binding: Binding) => boolean,
  ) {}

  /**
   * 动态窗口按 actor→phase→context 身份→day→stage→声明字段核验，末位才调用领域 current。
   * bind 在条件通过后先登记关闭记录，再捕获声明字段和顶层 pin；getter 抛错保该记录关闭，不能重新 bind 复活。
   * contextKeys 的列表副本属于本实例；它不校验深层提示、JSON 或字段类型，也不把这些字段当真实许可。
   */
  static window<Scope extends object>(
    queries: RequestLeaseWindowQueries<Scope>,
    order: number,
    contextKeys: readonly string[] = [],
  ): RequestLease<Scope, Scope, WindowBinding<Scope>> {
    const keys = [...contextKeys];
    return new RequestLease<Scope, Scope, WindowBinding<Scope>>(
      order,
      (scope, request, lease) => {
        if (
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase(scope) &&
          request.context.day === queries.day(scope) &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, lease.entry(scope, request, { scope, context: request.context, fields: [] }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          const binding = lease.records.get(request)!.turn.binding;
          for (const key of keys) binding.fields.push({ key, value: Reflect.get(binding.context, key) });
          lease.capture(request);
        }
      },
      (scope, request, binding) =>
        request.actorId === queries.actorId(scope) &&
        request.phase === queries.phase(scope) &&
        request.context === binding.context &&
        request.context.day === queries.day(scope) &&
        request.context.stage === queries.stage(scope) &&
        binding.fields.every(({ key, value }) => Object.is(Reflect.get(request.context, key), value)),
      (binding) => binding.scope,
      (binding) => binding.scope,
      sameIndexedFields,
      (_scope, binding) => queries.current(binding.scope),
    );
  }

  /** actor→phase→day→stage；查询还先核同一活跃 scope，末位晚核机制当前性。 */
  static actorPhaseDayStage<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, ScopeBinding<Scope>> {
    return new RequestLease<Owner, Scope, ScopeBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const scope = queries.active(owner);
        if (
          scope &&
          request.actorId === queries.actorId(scope) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.context.stage === queries.stage(scope)
        ) {
          lease.records.set(request, lease.entry(owner, request, { scope, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, binding) =>
        queries.owner(binding.scope) === owner &&
        queries.active(owner) === binding.scope &&
        request.actorId === queries.actorId(binding.scope) &&
        request.context === binding.context &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(binding.scope),
      (binding) => queries.owner(binding.scope),
      (binding) => binding.scope,
      sameIndexedFields,
      (_owner, binding) => queries.current(binding.scope),
    );
  }

  /** stage→phase→day→actor→current；查询保原 context→stage→day→phase→current 顺序和 Reflect.get 比较。 */
  static stagePhaseDayActor<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.context.stage === queries.stage(b) &&
          request.phase === queries.phase() &&
          request.context.day === 1 &&
          request.actorId === queries.actorId(b) &&
          queries.current(b)
        ) {
          lease.records.set(request, lease.entry(owner, request, { binding: b, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        request.phase === queries.phase() &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyReflectedField,
      () => true, // 原 matches 已在末位调用本族 current，不重复那一次。
    );
  }

  /** actor→phase→stage→day→current；查询的 phase 必须先于 context 身份，不重排成上一种协议。 */
  static actorPhaseStageDay<Owner, Scope>(
    queries: RequestLeaseCurrentQueries<Owner, Scope>,
    order: number,
  ): RequestLease<Owner, Scope, CurrentBinding<Scope>> {
    return new RequestLease<Owner, Scope, CurrentBinding<Scope>>(
      order,
      (owner, request, lease) => {
        const b = queries.active(owner);
        if (
          b &&
          request.actorId === queries.actorId(b) &&
          request.phase === queries.phase() &&
          request.context.stage === queries.stage(b) &&
          request.context.day === 1 &&
          queries.current(b)
        ) {
          lease.records.set(request, lease.entry(owner, request, { binding: b, context: request.context }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (owner, request, a) =>
        queries.owner(a.binding) === owner &&
        request.actorId === queries.actorId(a.binding) &&
        request.phase === queries.phase() &&
        request.context === a.context &&
        request.context.stage === queries.stage(a.binding) &&
        request.context.day === 1 &&
        queries.current(a.binding),
      (binding) => queries.owner(binding.binding),
      (binding) => binding.binding,
      everyIndexedField,
      () => true,
    );
  }

  /** 原物品入口只核 token/instance；phase/day/stage 留在查询，原作者当前性在查询成功后才晚核。 */
  static item<Owner, Scope, Author>(
    queries: RequestLeaseItemQueries<Owner, Scope, Author>,
    order: number,
  ): RequestLease<Owner, Scope, ItemBinding<Owner, Scope, Author>> {
    return new RequestLease<Owner, Scope, ItemBinding<Owner, Scope, Author>>(
      order,
      (world, request, lease) => {
        const a = queries.active(world),
          author = a == null ? undefined : queries.authors(a).get(request.actorId);
        if (
          a &&
          author &&
          request.context.wall_id === queries.token(a) &&
          request.context.item_instance_id === queries.instanceId(author)
        ) {
          lease.records.set(request, lease.entry(world, request, {
            scope: a,
            world,
            actorId: request.actorId,
            instanceId: queries.instanceId(author),
            context: request.context,
            author,
          }));
          registerRequestAliasPropagation(request, lease.order, lease.propagate);
          lease.capture(request);
        }
      },
      (world, request, binding) =>
        queries.active(world) === binding.scope &&
        request.actorId === binding.actorId &&
        request.context === binding.context &&
        request.context.wall_id === queries.token(binding.scope) &&
        request.context.item_instance_id === binding.instanceId &&
        request.phase === queries.phase() &&
        request.context.day === 1 &&
        request.context.stage === queries.stage(),
      (binding) => binding.world,
      (binding) => binding.scope,
      sameIndexedFields,
      (owner, binding) => queries.current(owner, binding.scope, binding.author),
    );
  }

  /** 条件与 set callee 保原位置；同对象已登记后不得重新 bind 来复活旧 turn。 */
  bind(owner: Owner, request: ActionRequest): void {
    if (this.records.has(request)) return;
    this.bindRequest(owner, request, this);
  }

  /** 只分配运行记录；原 binding/context 已在参数原位置读出。pin 在 set 与传播登记之后才读取。 */
  private entry(owner: Owner, original: ActionRequest, binding: Binding): LeaseEntry<Owner, Binding> {
    return { turn: { owner, original, binding, closed: true, settled: false, opened: false,
      completion: {}, aliases: new Set(), deadline: null }, retired: false, deadline: undefined };
  }

  private capture(request: ActionRequest): void {
    const entry = this.records.get(request)!, turn = entry.turn;
    // 捕获期间先保持关闭：新增 keys/getter 抛错保原已写记录／传播前缀，恢复字段也不重开。
    turn.pin = pinFields(request);
    entry.deadline = request.deadlineAtMs;
    turn.originalDeadline = entry.deadline;
    if (entry.deadline === undefined) turn.closed = false;
    else if (typeof entry.deadline === "number" && Number.isFinite(entry.deadline) && entry.deadline > Date.now()) {
      turn.deadline = entry.deadline;
      turn.closed = false;
    }
  }

  /** 外来 World／未登记请求先拒；alias 自身失配先隔离，不读取或毒化 original。 */
  scope(owner: Owner, request: ActionRequest): Scope | undefined {
    const entry = this.records.get(request);
    if (!entry || entry.turn.owner !== owner || entry.turn.closed || entry.retired) return;
    const turn = entry.turn;
    if (request !== turn.original) {
      try {
        if (!samePinnedFields(request, turn.pin!) || !Object.is(request.deadlineAtMs, entry.deadline)) {
          entry.retired = true;
          return;
        }
      } catch (error) {
        entry.retired = true;
        throw error;
      }
    }
    try {
      // 各协议仍按其声明的 ordered matches 查询 original；共同 context.stage 变坏会关共同 turn。
      if (!this.matches(owner, turn.original, turn.binding) ||
          !samePinnedFields(turn.original, turn.pin!) ||
          !Object.is(turn.original.deadlineAtMs, turn.originalDeadline) ||
          !this.domainCurrent(owner, turn.binding) ||
          (turn.deadline !== null && turn.deadline <= Date.now())) {
        turn.closed = true;
        return;
      }
      return this.bindingScope(turn.binding);
    } catch (error) {
      turn.closed = true;
      throw error;
    }
  }

  /**
   * 真正窗口在 create 后打开交付：各绑定实例不争写 guard。前后登记的 alias 同 guard／completion，
   * 这些引用只留本 owner 的运行集合，不挂 context。每个 Wall request 的 turn 独立于整个墙。
   */
  openDelivery(owner: Owner, request: ActionRequest): RequestLeaseTurn | undefined {
    if (!this.scope(owner, request)) return;
    const turn = this.records.get(request)!.turn;
    if (!turn.handle) turn.handle = {
      current: () => this.scope(owner, request) !== undefined,
      complete: () => this.finish(turn, true),
      close: () => this.finish(turn, false),
    };
    if (!turn.opened) {
      bindRequestDeliveryGuard(turn.original, () => this.scope(owner, turn.original) !== undefined, turn.completion);
      turn.opened = true;
      for (const alias of turn.aliases) this.bindDelivery(turn, alias);
    }
    return turn.handle;
  }

  private bindDelivery(turn: LeaseTurn<Owner, Binding>, request: ActionRequest): void {
    bindRequestDeliveryGuard(request, () => this.scope(turn.owner, request) !== undefined, turn.completion);
  }

  /** 付款结果只由真实窗口给出；不重查已被付款改变的 pending scope。先落终态再发一次通知。 */
  private finish(turn: LeaseTurn<Owner, Binding>, accepted: boolean): void {
    if (turn.settled) return;
    turn.closed = true;
    turn.settled = true;
    turn.aliases.clear();
    settleRequestDelivery(turn.completion, accepted);
  }

  /** 先核来源，再原 ordered fields，最后有限未来期限；坏目标／其 getter 异常不修改来源预算。 */
  private inherit(source: ActionRequest, target: ActionRequest): void {
    const sourceEntry = this.records.get(source);
    if (!sourceEntry || !this.scope(sourceEntry.turn.owner, source) || this.records.has(target)) return;
    if (!this.sameFields(source, target)) return;
    const turn = sourceEntry.turn;
    // 原 === 比较通过后仍须核 F02 pin（含 +0/-0 及晚 getter 原值）；非法目标不得先写记录／缩预算。
    if (!samePinnedFields(target, turn.pin!)) return;
    const deadline = target.deadlineAtMs;
    if (typeof deadline !== "number" || !Number.isFinite(deadline) || deadline <= Date.now() ||
        (turn.deadline !== null && deadline > turn.deadline)) return;
    this.records.set(target, { turn, retired: false, deadline });
    turn.deadline = deadline;
    turn.aliases.add(target);
    registerRequestAliasPropagation(target, this.order, this.propagate);
    if (turn.opened) this.bindDelivery(turn, target);
  }
}

/**
 * 负责装配一局游戏、收缩绝对期限、关闭运行资源并汇总失败。
 * 输入为已解析的对局设置与本次执行依赖；输出为记录结果和可选审计摘要。
 * 请求别名与原体权限仍由机制所有者校验；本模块保留停止、关闭、等待与落盘的顺序，
 * 后续失败不回滚已提交的动作，也不把可选摘要失败升级为对局失败。
 * Agent 与复现记录共用本局板子来源；maxDays 在原元数据读取处捕获，循环复用该值。
 */
import { deriveBoundedRequest } from "../core/domain/request_delivery";
import {
  animalOriginalAuditIds,
  animalOriginalAuditPlayer,
} from "../game/mechanisms/roles/animal_dream/roster";
import { aliveLifeDescriptor } from "../core/domain/components/alive";
import { initialPlayerIdentity } from "../core/domain/initial_roster";
import { initialIdentityDeal } from "../game/mechanisms/roles/initial_identity/deal";
import { text } from "@ai-werewolf-arena/game-text";
import { formatErrorDiagnostic } from "../utils/error_diagnostic";
/** 本局资源、期限、失败汇总与最终复盘由下方 runner 持有；导入不装配对局。 */
import path from "node:path";
import { bootstrapGame } from "../app/bootstrap";
import {
  COMPONENT,
  type ActionProvider,
  type ActionRequest,
  type AliveComponent,
  type RoleComponent,
  type RuntimeSnapshot,
  type ToolCall,
  type World,
  type IdentityComponent,
  createRandom,
} from "../core";
import type { ResolvedAgentRuntimeProfile } from "./config/contracts";
import type { ResolvedGameSetup } from "./config/resolve_game_setup";
import { resolvePlayerProfile } from "./config/resolve_game_setup";
import {
  createAcpConsoleLogger,
  createConsoleLog,
  presentGameResult,
  presentStreamEvents,
} from "./console_presenter";
import { GameEventRecorder } from "./game_event_recorder";
import {
  buildSessionId,
  resolveDefaultRecordRoot,
  SessionRecordManager,
} from "../recording/session_recorder";
import { runWithSessionRecorder } from "../recording/recording_context";
import { buildDebugSummaryMarkdown } from "../audit/debug_summary_generator";
import { createPlayerAgentRuntime, type PlayerAgentRuntime } from "./player_agent_factory";
import {
  beginGameReproduction,
  captureCheckpoint,
  currentEngineVersion,
} from "./simulation/reproduction_context";

/** 仅返回最终运行快照与领域事件总数；完整回放由会话记录器持久化。 */
export interface GameRunResult {
  snapshot: RuntimeSnapshot;
  eventCount: number;
}
/**
 * 每局独立的执行依赖，不进入玩家 DTO 或 JSON 配置。
 * 期限选择回调返回绝对时间，只参与取最小值；关闭观察回调接收脱离副本，异常归清理失败。
 */
export interface GameRunDependencies {
  selectRequestDeadline?: (
    request: Readonly<{
      actorId: number;
      day: number;
      stage: ActionRequest["context"]["stage"];
      ordinal: number;
      actorOrdinal: number;
      retryAttempt: number;
      nowMs: number;
    }>,
  ) => number | undefined;
  onRuntimeClosed?: (state: PlayerAgentRuntime["runtimeState"]) => void;
}

class DeadlineAwareActionProvider implements ActionProvider {
  private ordinal = 0;
  private readonly actors = new Map<number, number>();
  // 同一玩家／日期／stage 的重试沿用已记录预算；新尝试仍受全局与原请求期限限制。
  private readonly budgets = new Map<string, number>();
  constructor(
    private readonly delegate: ActionProvider,
    private readonly deadlineAtMs: number,
    private readonly timeoutMs: number,
    private readonly selectDeadline?: GameRunDependencies["selectRequestDeadline"],
  ) {}

  getAction(request: ActionRequest): Promise<ToolCall | null> {
    const nowMs = Date.now(),
      actorOrdinal = (this.actors.get(request.actorId) ?? 0) + 1;
    this.actors.set(request.actorId, actorOrdinal);
    const ordinal = ++this.ordinal;
    const retryAttempt = request.context.retry_attempt ?? 0;
    const selected = this.selectDeadline?.({
      actorId: request.actorId,
      day: request.context.day,
      stage: request.context.stage,
      ordinal,
      actorOrdinal,
      retryAttempt,
      nowMs,
    });
    if (selected !== undefined && !Number.isFinite(selected))
      throw new RangeError("game_request_deadline_invalid");
    const key = `${request.actorId}/${request.context.day}/${request.context.stage}`;
    // 期限只取最早绝对时间，重试不重置整份超时；运行时授权随原请求一起派生。
    const deadline = Math.min(
      this.deadlineAtMs,
      request.deadlineAtMs ?? Infinity,
      nowMs + this.timeoutMs,
      selected ?? Infinity,
      retryAttempt > 0 ? (this.budgets.get(key) ?? Infinity) : Infinity,
    );
    this.budgets.set(key, deadline);
    const timed = deriveBoundedRequest(request, deadline);
    return this.delegate.getAction(timed);
  }
}

/** 调用方先完成设置解析；这里装配并执行对局，不读取配置来源文件。 */
export async function runGame(
  setup: ResolvedGameSetup,
  dependencies: GameRunDependencies = {},
): Promise<GameRunResult> {
  const context = bootstrapGame(setup.boardConfig, {
    random: createRandom(setup.context.seed),
    locale: setup.context.locale,
    playerNames: Object.fromEntries(
      Object.entries(setup.players).flatMap(([seat, entry]) =>
        entry.name !== undefined ? [[seat, entry.name]] : [],
      ),
    ),
  });
  const profilesByActor = selectPlayerProfiles(context.world, setup);
  const sessionId = buildSessionId();
  const recordRoot = setup.options.recordRootDir ?? resolveDefaultRecordRoot();
  const replayManager = await SessionRecordManager.create(
    {
      sessionId,
      locale: setup.context.locale,
      board: setup.options.board,
      startedAtIso: new Date().toISOString(),
      random: context.random.metadata,
    },
    recordRoot,
    setup.context.displayLocale,
  );

  return runWithSessionRecorder(replayManager, async () => {
    const { options } = setup;
    const log = createConsoleLog(options.color);
    const startedAt = Date.now();
    const deadlineAtMs = startedAt + options.maxRuntimeMs;
    // 对局／记录失败统一汇总；并发动作和关闭失败暂存，收尾时按原顺序补入。
    const failures: unknown[] = [];
    const eventRecorder = new GameEventRecorder(
      {
        world: context.world,
        replayManager,
      },
      context.phaseManager.getSnapshot().phase,
    );
    const flushEvents = () => {
      const delta = eventRecorder.flush(context.phaseManager.getEvents());
      if (options.streamEvents)
        presentStreamEvents(delta, options.printPrivateEvents, log, setup.context.displayLocale);
    };
    let agentRuntime: PlayerAgentRuntime | undefined;
    let heartbeat: NodeJS.Timeout | undefined;
    let streamTimer: NodeJS.Timeout | undefined;
    let timedOut = false;
    // stopping 立即拒绝新动作和迟到回复；closing 合并关闭调用，inFlight 单独负责等待结算。
    let stopping = false;
    let closing: Promise<void> | undefined;
    const stopReason = new DOMException("game_actions_stopped", "AbortError");
    const inFlight = new Set<Promise<ToolCall | null>>();
    const actionFailures: unknown[] = [];
    const cleanupFailures: unknown[] = [];
    let maxDays: number;
    // 先撤运行入口，再异步关闭 Agent；关闭异常暂存，不能覆盖触发停止的原始失败。
    const closeRuntime = (): Promise<void> => {
      stopping = true;
      closing ??= Promise.resolve()
        .then(() => agentRuntime?.close())
        .catch((error) => {
          cleanupFailures.push(error);
        });
      return closing;
    };
    const drainActions = async () => {
      while (inFlight.size) await Promise.allSettled([...inFlight]);
    };

    try {
      const reproduction = beginGameReproduction(replayManager, context, {
        engine: await currentEngineVersion(),
        boardId: options.board,
        locale: context.world.locale,
        maxDays: (maxDays = options.maxDays),
        profiles: profilesByActor,
      });
      agentRuntime = await createPlayerAgentRuntime({
        world: context.world,
        boardConfig: context.boardConfig,
        profilesByActor,
        acpWorkspaceRoot: path.join(recordRoot, sessionId, "acp-workspaces"),
        llmTimeoutMs: options.llmTimeoutMs,
        trace: options.trace,
        displayLocale: setup.context.displayLocale,
        colorizeLogs: options.color,
        printLlmIo: options.printLlmIo,
        printThinking: options.printThinking,
        createAcpUpdateObserver:
          options.printThinking || options.printLlmIo
            ? (actorId) =>
                createAcpConsoleLogger(actorId, log, setup.context.displayLocale, {
                  printThinking: options.printThinking,
                  printLlmIo: options.printLlmIo,
                })
            : undefined,
      });
      const selectedProvider: ActionProvider = {
        async getAction(request) {
          if (stopping) throw stopReason;
          const action = await agentRuntime!.provider.getAction(request);
          if (stopping) throw stopReason;
          return action;
        },
      };
      const decisionProvider: ActionProvider = {
        getAction: (request) => {
          const decision = reproduction.decide(request, selectedProvider);
          let tracked!: Promise<ToolCall | null>;
          tracked = decision.then(
            (action) => {
              inFlight.delete(tracked);
              return action;
            },
            (error) => {
              inFlight.delete(tracked);
              if (error !== stopReason) actionFailures.push(error);
              // 保留记录器已写的决策前缀，再开始取消其它动作，保留原异常的因果先后。
              void closeRuntime();
              throw error;
            },
          );
          inFlight.add(tracked);
          return tracked;
        },
      };
      const provider = new DeadlineAwareActionProvider(
        decisionProvider,
        deadlineAtMs,
        options.llmTimeoutMs,
        dependencies.selectRequestDeadline,
      );
      log(
        `[run_game] start board=${options.board} replay_session_id=${sessionId} record_dir=${replayManager.sessionDir} · ${text(setup.context.displayLocale, "runtime.start")}`,
        "info",
      );

      if (options.trace) {
        heartbeat = setInterval(() => {
          const snapshot = context.phaseManager.getSnapshot();
          log(
            `[run_game] heartbeat day=${snapshot.day} phase=${snapshot.phase} gameOver=${snapshot.gameOver} elapsed_ms=${Date.now() - startedAt} · ${text(setup.context.displayLocale, "runtime.heartbeat")}`,
            "muted",
          );
        }, 5000);
      }
      streamTimer = setInterval(() => {
        try {
          flushEvents();
        } catch (error) {
          failures.push(error);
          replayManager.noteReproductionFailure("recording", error);
          void closeRuntime();
          if (streamTimer) clearInterval(streamTimer);
        }
      }, 1000);

      let cycle = 0;
      while (!context.phaseManager.getSnapshot().gameOver && failures.length === 0) {
        const elapsed = Date.now() - startedAt;
        if (elapsed >= options.maxRuntimeMs) {
          timedOut = true;
          log(
            `[run_game] runtime_timeout elapsed_ms=${elapsed} · ${text(setup.context.displayLocale, "runtime.timeout")}`,
            "warn",
          );
          break;
        }
        cycle++;
        let complete = false;
        let cycleFailure: unknown;
        try {
          await context.phaseManager.runSingleCycle(provider, maxDays);
          complete = true;
        } catch (error) {
          cycleFailure = error;
          if (error !== stopReason) failures.push(error);
          replayManager.noteReproductionFailure("cycle", error);
          await closeRuntime();
          await drainActions();
        }
        // 无论周期成功或失败都保存实际结算前缀；失败周期先关闭并等待已在途动作。
        try {
          reproduction.checkpoint(
            captureCheckpoint(
              context.world,
              context.phaseManager.getSnapshot(),
              cycle,
              complete,
              context.phaseManager.getEvents().length,
              cycleFailure,
            ),
            context.phaseManager.getEvents(),
          );
        } catch (error) {
          failures.push(error);
          reproduction.invalidate();
          replayManager.noteReproductionFailure("recording", error);
        }
        if (failures.length) break;
        const snapshot = context.phaseManager.getSnapshot();
        log(
          `[run_game] cycle day=${snapshot.day} phase=${snapshot.phase} gameOver=${snapshot.gameOver} elapsed_ms=${Date.now() - startedAt} · ${text(setup.context.displayLocale, "runtime.cycle")}`,
          "info",
        );
      }
    } catch (error) {
      failures.push(error);
      replayManager.noteReproductionFailure("initialization", error);
    } finally {
      // 先停定时任务并补事件，再关闭／等待动作；最终记录只在这些原收尾步骤之后发布。
      if (heartbeat) clearInterval(heartbeat);
      if (streamTimer) clearInterval(streamTimer);
      try {
        flushEvents();
      } catch (error) {
        failures.push(error);
        replayManager.noteReproductionFailure("recording", error);
      }
      await closeRuntime();
      await drainActions();
      if (agentRuntime && dependencies.onRuntimeClosed) {
        try {
          dependencies.onRuntimeClosed(structuredClone(agentRuntime.runtimeState));
        } catch (error) {
          cleanupFailures.push(error);
        }
      }
      // 取消标记不列为独立动作错误；原异常按引用去重，清理失败仍按发生顺序追加。
      for (const error of actionFailures)
        if (!failures.includes(error)) {
          failures.push(error);
          replayManager.noteReproductionFailure("controller", error);
        }
      for (const error of cleanupFailures) {
        failures.push(error);
        replayManager.noteReproductionFailure("cleanup", error);
      }
      try {
        const snapshot = context.phaseManager.getSnapshot();
        const summaryInput = await replayManager.finalize({
          endedAtIso: new Date().toISOString(),
          winner: snapshot.result?.winner ?? null,
          ...(snapshot.result ? { gameResult: snapshot.result } : {}),
          finishReason: failures.length
            ? "runtime_error"
            : (snapshot.result?.reason ?? (timedOut ? "runtime_timeout" : "completed")),
          players: replayPlayers(context.world),
        });
        // 核心终档失败进入汇总；诊断摘要为可选输出，其异常只写日志。
        try {
          await replayManager.writeDebugSummary(
            await buildDebugSummaryMarkdown(
              {
                ...summaryInput,
                locale: setup.context.locale,
                displayLocale: setup.context.displayLocale,
              },
              setup.audit,
            ),
          );
        } catch (error) {
          log(
            `[audit] debug_summary_failed err=${formatErrorDiagnostic(error, setup.context.displayLocale)}`,
            "warn",
          );
        }
      } catch (error) {
        failures.push(error);
      }
    }

    if (failures.length === 1) throw failures[0];
    if (failures.length > 1) throw new AggregateError(failures, "game_run_failed");
    const snapshot = context.phaseManager.getSnapshot();
    const events = context.phaseManager.getEvents();
    presentGameResult({
      locale: setup.context.displayLocale,
      board: options.board,
      snapshot,
      events,
      timedOut,
      printAllEvents: options.printAllEvents,
      printChat: options.printChat,
      streamEvents: options.streamEvents,
      log,
    });
    return { snapshot, eventCount: events.length };
  });
}

function selectPlayerProfiles(
  world: World,
  setup: ResolvedGameSetup,
): Map<number, ResolvedAgentRuntimeProfile> {
  const profiles = new Map<number, ResolvedAgentRuntimeProfile>();
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role)?.role;
    profiles.set(id, resolvePlayerProfile(setup, id, role));
  }
  return profiles;
}

/**
 * 构造 God 终档的身份记录，不复用玩家观察视图。
 * 动物梦境读取已捕获的原名单／身份与原生命；初始身份机制保留原发牌，普通局使用当前组件。
 */
function replayPlayers(world: World) {
  const originalIds = animalOriginalAuditIds(world);
  if (originalIds)
    return originalIds.map((id) => {
      const original = animalOriginalAuditPlayer(world, id)!,
        identity = JSON.parse(original.identityJson);
      return {
        player_id: id,
        role: original.scope.roleId,
        camp: original.scope.campValue,
        alive: aliveLifeDescriptor(original.scope.life)!.get!.call(original.scope.life),
        name: identity.name,
      };
    });
  // 原名单／开局牌组是历史数据；仅普通fallback在原字段位置查询当前Camp。
  const initial = initialIdentityDeal(world);
  return world.entityIds().map((id, index) => {
    const role = world.getComponent(id, COMPONENT.Role);
    return {
      player_id: id,
      role: initialPlayerIdentity(world, id)?.role ?? initial?.[index] ?? role?.role ?? "unknown",
      camp:
        initialPlayerIdentity(world, id)?.camp ??
        (initial ? (initial[index] === "wolf" ? "wolf" : "good") : ((role && world.getComponent(id, COMPONENT.Camp)?.camp) ?? "unknown")),
      alive: world.getComponent(id, COMPONENT.Alive)?.alive === true,
      name: world.getComponent(id, COMPONENT.Identity)?.name,
    };
  });
}
